#!/usr/bin/env python3
"""Original bilingual environment/urban teaching inputs b401-b425.
All numerical values in the method bank are hypothetical teaching data.
Official sources establish project identity/process; they do not certify examples.
"""
from pathlib import Path
import json, math, copy
ROOT=Path(__file__).resolve().parents[1]
TARGETS={x['id']:x for x in json.loads((ROOT/'targets.json').read_text())}
M={}
def p(zh,en): return zh+'~'+en
def method(key,title,mechanism,givens,formula,expr,unit,boundary,verify,failure,wrong,change,expr2):
    M[key]=dict(title=title,mechanism=mechanism,givens=givens,formula=formula,expr=expr,unit=unit,boundary=boundary,verify=verify,failure=failure,wrong=wrong,change=change,expr2=expr2)

# Water collection, treatment, and membrane/reuse methods.
method('load',p('污染負荷與採樣邊界','Pollutant load and sampling boundary'),p('污染負荷是流量與濃度的乘積；瞬間低濃度可能只是雨水稀釋，不能單憑濃度推論污染總量下降。','Pollutant load is flow times concentration; a low concentration can result from rainwater dilution without a decrease in mass.'),p('日流量 Q=1200 m³/d、流量加權濃度 C=180 mg/L','daily flow Q=1200 m³/d and flow-weighted concentration C=180 mg/L'),'L=QC/1000','1200*180/1000','kg/d',p('採樣與流量必須涵蓋相同時窗；未包括管線內累積。','Sampling and flow must cover the same time interval; accumulation in the sewer is omitted.'),p('將同一總時窗切成三段，以各段平均流率 Qi（m³/d）、濃度 Ci（mg/L）與時長 Δti（d）算質量 Mi=QiCiΔti/1000（kg）；加總質量後除以總時長，得到平均負荷率（kg/d），再與相同總時窗的流量加權混合樣比對。','Split the same total sampling window into three intervals. For each interval use mean flow Qi (m³/d), concentration Ci (mg/L) and duration Δti (d) to calculate mass Mi=QiCiΔti/1000 (kg). Sum the masses and divide by total duration to obtain mean loading (kg/d), then compare with a flow-weighted composite covering that same total window.'),p('等時間採樣遇到尖峰流量會低估負荷，先檢查採樣權重。','Equal-time sampling during a flow peak can understate loading; inspect sampling weights first.'),p('濃度較低就表示污染質量一定較少。','Lower concentration necessarily means less pollutant mass.'),p('只把流量改成1500 m³/d','change only flow to1500 m³/d'),'1500*180/1000')
method('hrt',p('水力停留時間','Hydraulic retention time'),p('名目停留時間 V/Q 是容積周轉時間；短流與死區會使實際停留時間分布偏離此平均值。','Nominal retention V/Q is a volume turnover time; short-circuiting and dead zones distort the actual residence-time distribution.'),p('有效容積 V=800 m³、流量 Q=2400 m³/d','effective volume V=800 m³ and flow Q=2400 m³/d'),'t=24V/Q','24*800/2400','h',p('有效容積不含不可用空間；不代表所有水團均停留同樣久。','Effective volume excludes unusable space; not every parcel remains for the same duration.'),p('用示蹤突破曲線比較平均停留與最早突破，保留流量紀錄。','Compare tracer mean residence and early breakthrough while retaining flow records.'),p('隔板破損可能造成短流；擴大容積未必能消除捷徑。','A broken baffle may create short-circuiting; a larger volume need not remove the shortcut.'),p('V/Q 就是每一滴水的精確停留時間。','V/Q is the exact residence time of every drop.'),p('只把有效容積改成600 m³','change only effective volume to600 m³'),'24*600/2400')
method('peak',p('尖峰流量與可用能力','Peak flow and available capacity'),p('平均流量用於年收支，尖峰流量決定瞬時水力負荷；泵站、攔污與沉澱單元可能有不同瓶頸。','Mean flow supports annual balances, whereas peak flow governs instantaneous hydraulics; pumps, screens and clarifiers may have different bottlenecks.'),p('平均 Q=0.8 m³/s、假設尖峰係數 f=2.5','mean Q=0.8 m³/s and assumed peak factor f=2.5'),'Qp=fQ','0.8*2.5','m³/s',p('係數為假設，不能代替地方降雨與下水道時序分析。','The assumed factor does not replace local rainfall and sewer time-series analysis.'),p('把尖峰歷線疊在各單元可用能力上，找出最早溢流點。','Overlay the peak hydrograph on available capacity for each unit and identify the first overflow point.'),p('把設計總能力當成檢修時可用能力，會漏算停機風險。','Using installed capacity during maintenance overlooks unavailable equipment.'),p('平均流量通過即可證明暴雨時不溢流。','Passing mean flow proves that storm overflows cannot occur.'),p('只把尖峰係數改成3','change only the peak factor to3'),'0.8*3')
method('velocity',p('流速與通水斷面','Velocity and flow area'),p('連續方程 Q=Av 將流量連到平均流速；局部收縮與阻塞提高流速及水頭損失。','Continuity Q=Av links discharge to mean velocity; local contraction and blockage increase velocity and head loss.'),p('流量 Q=0.9 m³/s、有效面積 A=0.6 m²','flow Q=0.9 m³/s and clear area A=0.6 m²'),'v=Q/A','0.9/0.6','m/s',p('均勻平均流；不能用平均流速判定局部沖刷或人員安全。','Uniform mean flow; local scour or human safety cannot be inferred from mean velocity alone.'),p('比較水位、流量與有效面積，再以斷面多點量測查偏流。','Compare level, flow and clear area, then inspect nonuniformity with multiple section measurements.'),p('只使用名目斷面會忽略攔污物或沉積造成的縮減。','Nominal area misses reductions caused by debris or sediment.'),p('阻塞不會改變同一流量下的流速。','Blockage cannot change velocity at the same flow.'),p('只把有效面積減至0.45 m²','reduce only clear area to0.45 m²'),'0.9/0.45')
method('manning',p('重力輸送與粗糙度','Gravity conveyance and roughness'),p('Manning 模型以水力半徑、坡度與粗糙度表示明渠平均輸送能力；加粗表面會降低同水位的流量。','The Manning model relates open-channel capacity to hydraulic radius, slope and roughness; greater roughness reduces discharge at the same depth.'),p('A=4 m²、R=0.8 m、S=0.001、n=0.015','A=4 m², R=0.8 m, S=0.001 and n=0.015'),'Q=(A/n)R^(2/3)S^(1/2)','(4/0.015)*0.8**(2/3)*0.001**0.5','m³/s',p('穩定均勻明渠近似；滿管壓力、回水與跌水需另建模。','Steady uniform open-channel approximation; pressure flow, backwater and drops require separate models.'),p('量測縱坡與斷面，校準不同水位的流量曲線。','Measure slope and section and calibrate the discharge curve at several depths.'),p('沉積與生物膜改變粗糙度，沿用初建值可能高估能力。','Sediment and biofilm alter roughness; an as-built value may overestimate capacity.'),p('同一斷面輸送能力與粗糙度無關。','Capacity of the same section is independent of roughness.'),p('只把 n 改成0.020','change only n to0.020'),'(4/0.020)*0.8**(2/3)*0.001**0.5')
method('storage',p('調蓄與連續方程','Storage and continuity'),p('調蓄量隨入流減出流累積；容積夠大仍須確認退水能力，否則下一場雨開始時未必為空。','Storage accumulates inflow minus outflow; sufficient geometric volume is not enough if drawdown leaves it occupied before the next storm.'),p('一小時內 Qin=2.0 m³/s、Qout=0.6 m³/s','over one hour Qin=2.0 m³/s and Qout=0.6 m³/s'),'ΔV=(Qin-Qout)Δt','(2.0-0.6)*3600','m³',p('矩形單一歷線且無滲漏；真實設計必須積分完整降雨歷線。','One rectangular hydrograph without leakage; real design must integrate the full event hydrograph.'),p('以五分鐘資料逐步積分，再與水位—容積曲線核對。','Integrate five-minute data and compare with the stage-storage curve.'),p('水位計零點漂移會看似增加儲量，需獨立水尺確認。','Level-sensor zero drift can mimic storage gain; confirm with an independent staff gauge.'),p('最大容積等於每場雨都可用的容積。','Maximum volume equals the available volume for every storm.'),p('只把出流提高到0.8 m³/s','increase only outflow to0.8 m³/s'),'(2.0-0.8)*3600')
method('pump',p('提升水頭與電力','Lift head and electrical power'),p('泵的輸入功率須供應流量的位能增加及損失；效率下降會使同一輸送服務耗電增加。','Pump input must provide the hydraulic energy increase and losses; lower efficiency increases electricity for the same conveyance service.'),p('Q=0.10 m³/s、H=12 m、總效率η=0.72、ρ=1000 kg/m³','Q=0.10 m³/s, H=12 m, total efficiencyη=0.72 and ρ=1000 kg/m³'),'P=ρgQH/(1000η)','1000*9.81*0.10*12/(1000*0.72)','kW',p('穩態不可壓縮流，H含管損；不涵蓋起動、水錘與汽蝕。','Steady incompressible flow with friction included in H; starting, surge and cavitation are excluded.'),p('同步量測流量、進出口壓差與真實功率，勿把視在功率當耗電。','Synchronize flow, pressure difference and real-power measurements; do not confuse apparent and real power.'),p('葉輪磨損或閥門節流會改變工作點，須查泵曲線。','Impeller wear or throttling changes the operating point; inspect the pump curve.'),p('相同流量下所有泵的耗電都相同。','All pumps consume the same power at equal flow.'),p('只把效率降成0.60','reduce only efficiency to0.60'),'1000*9.81*0.10*12/(1000*0.60)')
method('clarify',p('表面溢流率與沉降分離','Surface loading and settling separation'),p('理想沉澱中顆粒沉速相對於表面溢流率決定是否捕集；增加深度主要改變停留與污泥儲存，不能取代表面積。','In ideal settling, particle settling speed relative to surface overflow rate governs capture; greater depth changes retention and sludge storage but cannot replace surface area.'),p('Q=6000 m³/d、表面積 A=300 m²','Q=6000 m³/d and surface area A=300 m²'),'v0=Q/A','6000/300','m/d',p('理想離散顆粒近似；絮凝、污泥濃縮、風與短流另行檢核。','Ideal discrete-particle approximation; flocculation, thickening, wind and short-circuiting need separate checks.'),p('用沉降柱與進出水SS比對捕集，不把水清澈當溶解物已去除。','Compare a settling-column test and inlet/outlet SS; clear water does not prove dissolved contaminants were removed.'),p('排泥不良會讓泥層抬升，造成出水固體增加。','Poor sludge withdrawal raises the sludge blanket and increases effluent solids.'),p('只要把池挖深就能任意增加沉澱流量。','Making a tank deeper permits unlimited settling flow.'),p('只把面積加至400 m²','increase only area to400 m²'),'6000/400')
method('removal',p('去除效率與質量去向','Removal efficiency and mass destination'),p('去除是污染物由水相移到污泥或被轉化；以相同流量比較濃度可估效率，但不能省略副產物流。','Removal moves pollutants from water to solids or transforms them; concentration comparison estimates efficiency at equal flows but does not eliminate residual streams.'),p('Cin=200 mg/L、Cout=40 mg/L且進出水量相同','Cin=200 mg/L and Cout=40 mg/L at equal inlet and outlet flows'),'η=100(Cin-Cout)/Cin','100*(200-40)/200','%',p('只適用同一物種、同時窗且等流量；不能代替總污染收支。','Same species, time window and flow only; not a replacement for a complete pollutant balance.'),p('同時量測污泥固體量與水相濃度，對照移除質量。','Measure sludge solids and water concentrations together to reconcile removed mass.'),p('以清水稀釋取代處理會讓濃度變低但不一定減少排放質量。','Dilution can lower concentration without lowering discharge mass.'),p('看不到的污染物代表已完全被破壞。','An invisible pollutant has been completely destroyed.'),p('只把出水改成60 mg/L','change only effluent to60 mg/L'),'100*(200-60)/200')
method('mf',p('膜通量與有效膜面積','Membrane flux and effective area'),p('膜通量是單位膜面積的產水速率；產水流量固定時，增加可用膜面積可降低通量負擔。','Membrane flux is permeate flow per area; additional available membrane area reduces flux loading at fixed production.'),p('產水 Qp=96 m³/h、膜面積 A=2400 m²','permeate Qp=96 m³/h and membrane area A=2400 m²'),'J=1000Qp/A','1000*96/2400','L/(m²·h)',p('淨產水通量；應另扣反洗停機，非任何膜產品允許值。','Net production flux; backwash downtime is separate and this is not a membrane product limit.'),p('以產水總表與各膜列面積核對，另記反洗時間。','Reconcile total permeate with each train area and separately log backwash time.'),p('未扣停用膜列會低估剩餘膜列的真實通量。','Counting offline trains understates flux on the remaining membranes.'),p('膜面積減半但產水不變時通量不變。','Flux stays unchanged when membrane area halves at constant production.'),p('只把可用膜面積降成1920 m²','reduce only active membrane area to1920 m²'),'1000*96/1920')
method('tmp',p('跨膜壓差與比通量','Transmembrane pressure and permeability'),p('相同溫度下，通量除以跨膜壓差可作為表觀水力透過率；降低代表阻力增加，但未直接指出污染種類。','At the same temperature, flux divided by transmembrane pressure gives apparent permeability; a decrease indicates more resistance but not its chemical cause.'),p('J=30 L/(m²·h)、TMP=0.15 bar','J=30 L/(m²·h) and TMP=0.15 bar'),'Lp=J/TMP','30/0.15','L/(m²·h·bar)',p('先做溫度校正；僅為操作趨勢，不是膜材本徵常數。','Apply temperature correction first; an operational trend, not an intrinsic material constant.'),p('比較相同溫度與流量的前後資料，測壓點須一致。','Compare before/after data at equal temperature and flow with identical pressure taps.'),p('堵塞與水溫下降都會降低比通量，先分離兩種原因。','Fouling and colder water both lower permeability; distinguish these causes first.'),p('跨膜壓差越大必定代表膜更乾淨。','Higher transmembrane pressure always means a cleaner membrane.'),p('只把 TMP升成0.20 bar','increase only TMP to0.20 bar'),'30/0.20')
method('recovery',p('逆滲透水回收率','Reverse-osmosis water recovery'),p('回收率把進水分為產水與濃水；提高回收通常也提高濃水鹽度與結垢風險，不能只追求產水百分比。','Recovery divides feed into permeate and concentrate; higher recovery usually raises concentrate salinity and scaling risk, so production percentage alone is insufficient.'),p('進水 Qf=100 m³/h、產水 Qp=75 m³/h','feed Qf=100 m³/h and permeate Qp=75 m³/h'),'Y=100Qp/Qf','100*75/100','%',p('穩態體積流量且忽略微小密度差；未預測結垢。','Steady volumetric flow with small density differences neglected; scaling is not predicted.'),p('校核Qf=Qp+Qc，檢查三支流量表的時間同步。','Check Qf=Qp+Qc and synchronize the three flow meters.'),p('濃水表偏低會製造虛假的高回收，須做總水量平衡。','An under-reading concentrate meter creates false high recovery; close the water balance.'),p('回收率越接近百分之百就一定越好。','Recovery closer to one hundred percent is always preferable.'),p('只把產水量改成80 m³/h','change only permeate to80 m³/h'),'100*80/100')
method('rejection',p('鹽分截留與導電度指標','Salt rejection and conductivity indicators'),p('截留率比較進水與產水的同一溶質；導電度是混合離子指標，不能證明所有微量有機物均被截留。','Rejection compares the same solute in feed and permeate; conductivity reflects mixed ions and does not prove retention of every trace organic.'),p('同一溶質Cf=500 mg/L、Cp=5 mg/L','same solute Cf=500 mg/L and Cp=5 mg/L'),'R=100(1-Cp/Cf)','100*(1-5/500)','%',p('示範單一溶質與配對採樣；離子組成改變需校正導電度解釋。','One solute and paired sampling; changed ionic composition requires reinterpretation of conductivity.'),p('以標準液校正導電度，並用實驗室分析驗證目標溶質。','Calibrate conductivity with standards and verify the target solute with laboratory analysis.'),p('膜破損、密封旁通與探頭漂移都可能使產水讀值上升。','Membrane damage, seal bypass and sensor drift can all raise the permeate reading.'),p('高鹽截留率等同所有污染物百分之百去除。','High salt rejection means complete removal of every pollutant.'),p('只把Cp改成10 mg/L','change only Cp to10 mg/L'),'100*(1-10/500)')
method('brine',p('濃水鹽分收支','Concentrate salt balance'),p('被截留的鹽須從濃水排出；水量與鹽量兩條守恆式共同決定濃水濃度。','Rejected salt exits in concentrate; conservation of both water and salt determines concentrate concentration.'),p('Qf=100、Qp=75 m³/h；Cf=500、Cp=5 mg/L','Qf=100 and Qp=75 m³/h; Cf=500 and Cp=5 mg/L'),'Cc=(QfCf-QpCp)/(Qf-Qp)','(100*500-75*5)/(100-75)','mg/L',p('穩態無沉澱及吸附；若鹽析出，此式不能描述固相。','Steady flow without precipitation or adsorption; precipitated solids require another balance.'),p('以進水、產水與濃水三點配對樣核對鹽負荷。','Use paired samples of feed, permeate and concentrate to check salt loads.'),p('只計產水品質而不計濃水，會把污染轉移誤認成消失。','Checking only permeate quality mistakes transferred pollution for disappearance.'),p('膜截留的鹽會在系統內自動消失。','Salt rejected by the membrane disappears automatically.'),p('只把Qp改成80 m³/h，Cp固定','change only Qp to80 m³/h while holding Cp fixed'),'(100*500-80*5)/(100-80)')
method('roenergy',p('高壓分離比能耗','Specific energy of pressure separation'),p('壓力功等於壓差乘流量；折算成每立方米產水時，回收率與效率都進入分母。','Pressure work equals pressure difference times flow; recovery and efficiency both enter the denominator when normalized per cubic metre of permeate.'),p('壓差Δp=10 bar、η=0.80、回收率Y=0.75','pressure differenceΔp=10 bar,η=0.80 and recoveryY=0.75'),'SEC=Δp/(36ηY)','10/(36*0.80*0.75)','kWh/m³',p('未含能量回收、預處理與其他廠用電；不是整廠能耗。','Excludes energy recovery, pretreatment and auxiliary loads; not whole-plant consumption.'),p('把高壓泵電表與產水體積在相同時窗相除，再列其他負載。','Divide high-pressure pump energy by permeate volume over the same interval and list other loads separately.'),p('用進水體積當分母會低估每單位產水能耗。','Using feed volume as the denominator understates energy per unit product.'),p('泵壓力功就是整廠總用電。','Pump pressure work equals total plant electricity.'),p('只把壓差增成12 bar','increase only pressure difference to12 bar'),'12/(36*0.80*0.75)')
method('uv',p('紫外線光量概念','Ultraviolet fluence concept'),p('均勻光場下光量為強度乘照射時間；真實反應器須考慮水質透光率、遮蔽與停留分布。','In a uniform field, fluence equals intensity times exposure time; real reactors require transmittance, shadowing and residence distributions.'),p('假想均勻強度I=2 mW/cm²、照射t=15 s','hypothetical uniform intensity I=2 mW/cm² and exposuret=15 s'),'H=It','2*15','mJ/cm²',p('僅單位換算練習，不是病原體認證劑量或飲用水安全判準。','Unit-conversion exercise only; not a validated pathogen dose or drinking-water safety criterion.'),p('比較燈強度、透光率與流量，指出單一探頭代表不了所有流線。','Compare lamp intensity, transmittance and flow, explaining why one sensor does not represent all streamlines.'),p('套管結垢與水中懸浮物可同時降低有效光量。','Sleeve fouling and suspended particles can both reduce effective fluence.'),p('燈亮著就表示所有水都接受相同且足夠的光量。','An illuminated lamp means every parcel receives the same sufficient fluence.'),p('只把假想強度降成1.5 mW/cm²','reduce only hypothetical intensity to1.5 mW/cm²'),'1.5*15')
method('log',p('多重障壁與對數去除','Multiple barriers and log reduction'),p('對數去除以濃度比表示，不同障壁只有在適用同一目標且經驗證時才可合併計分。','Log reduction expresses a concentration ratio; barrier credits combine only for the same target under validated conditions.'),p('假想指標Nin=100000、Nout=100 每單位體積','hypothetical indicator Nin=100000 and Nout=100 per unit volume'),'LRV=log10(Nin/Nout)','math.log10(100000/100)','log10',p('純數學示範，檢出限及實際核准信用未包含。','Mathematical demonstration only; detection limits and approved treatment credits are excluded.'),p('紀錄檢出限，區分未檢出與零；檢查共同失效是否影響多個障壁。','Record detection limits, distinguish non-detect from zero, and inspect common failures across barriers.'),p('把未檢出當零會算出無限去除，失去可驗證性。','Treating non-detect as zero gives infinite removal and is unverifiable.'),p('兩個未驗證障壁的標稱數值可以直接當認證效果。','Nominal values for two unvalidated barriers can be treated as certified performance.'),p('只把Nout改成1000','change only Nout to1000'),'math.log10(100000/1000)')
method('blend',p('回用水混合與需求配對','Reuse blending and demand matching'),p('混合濃度由各水流的質量加權，而不是簡單平均；不同用途的需求與品質應分別核對。','Blended concentration is mass weighted rather than a simple average; quality and demand must be checked separately for each reuse.'),p('Q1=80、Q2=20 m³/h；C1=5、C2=100 mg/L','Q1=80 and Q2=20 m³/h; C1=5 and C2=100 mg/L'),'Cmix=(Q1C1+Q2C2)/(Q1+Q2)','(80*5+20*100)/(80+20)','mg/L',p('同一可加成保守溶質；微生物風險與化學相容性不能僅靠此式判斷。','One additive conservative solute; microbial risk and chemical compatibility cannot be established by this formula.'),p('檢查流量權重與採樣位置，再用混合後樣品驗證。','Inspect flow weights and sampling locations and verify with a downstream mixed sample.'),p('混合未完全就採樣會得到隨位置不同的濃度。','Sampling before complete mixing yields position-dependent concentrations.'),p('兩股不同流量的濃度總可直接取平均。','Concentrations of unequal flows can always be averaged directly.'),p('只把Q2改成40 m³/h','change only Q2 to40 m³/h'),'(80*5+40*100)/(80+40)')
method('darcy',p('補注與達西流','Recharge and Darcy flow'),p('飽和多孔介質中的達西通量取決於水力傳導係數與梯度；達西流速不是孔隙內水的速度。','Darcy flux in saturated porous media depends on hydraulic conductivity and gradient; it is not the pore-water velocity.'),p('K=5 m/d、梯度i=0.02、截面A=2000 m²','K=5 m/d, gradienti=0.02 and cross-sectionA=2000 m²'),'Q=KiA','5*0.02*2000','m³/d',p('均質飽和一維近似；不處理裂隙優勢流或非飽和區。','Homogeneous saturated one-dimensional approximation; fractures and the unsaturated zone are excluded.'),p('以觀測井水頭求梯度，分開估計K與有效孔隙率。','Use observation-well heads to estimate gradient and estimate K separately from effective porosity.'),p('細粒堵塞可降低K，即使水頭相同補注率仍會下降。','Fine-particle clogging can reduce K and recharge at the same head.'),p('達西流速與孔隙水流速必定相同。','Darcy flux always equals pore-water velocity.'),p('只把K減成3 m/d','reduce only K to3 m/d'),'3*0.02*2000')
method('travel',p('地下水名目傳輸時間','Nominal groundwater travel time'),p('孔隙水速度約為Ki/ne；傳輸時間還受彌散、吸附及優勢流影響。','Pore-water velocity is approximately Ki/ne; dispersion, sorption and preferential flow further influence travel.'),p('距離L=100 m、有效孔隙率ne=0.25、K=5 m/d、i=0.02','distanceL=100 m, effective porosityne=0.25, K=5 m/d andi=0.02'),'t=Lne/(Ki)','100*0.25/(5*0.02)','d',p('均質平流示範，不是衛生防護距離或實際最短停留時間。','Homogeneous advective example; not a sanitary setback or actual minimum residence time.'),p('用保守示蹤與觀測井分布比較最早突破，不能只看平均。','Compare early breakthrough using a conservative tracer and monitoring wells, not only the mean.'),p('砂礫透鏡造成的快速通道會使平均模型過於樂觀。','A permeable gravel lens can make the mean model overoptimistic.'),p('平均傳輸時間保證所有污染物都有同樣衰減。','Mean travel time guarantees identical attenuation for all contaminants.'),p('只把梯度改成0.04','change only gradient to0.04'),'100*0.25/(5*0.04)')
method('availability',p('備援與共同失效','Redundancy and common failures'),p('平行備援可降低獨立停機造成的服務中斷，但共同電源、進水或控制器會破壞獨立假設。','Parallel redundancy reduces outages from independent failures, but common power, feed or controllers invalidate independence.'),p('兩列各自可用率A=0.95且任一列足以供應示範負載','two trains each have availabilityA=0.95 and either meets the hypothetical load'),'Asys=1-(1-A)^2','1-(1-0.95)**2','fraction',p('僅兩列獨立且容量足夠；不含共同失效或修復時間分布。','Two independent adequate-capacity trains only; common failures and repair-time distributions are excluded.'),p('畫故障樹並標出共享設備，測試單列退出時的完整流程。','Draw a fault tree marking shared assets and replay the process with one train unavailable.'),p('兩列共用一個關鍵閥門，該閥失效仍會同時停產。','A shared critical valve can stop both trains together.'),p('設備數量加倍就能消除所有停機。','Doubling equipment eliminates every outage.'),p('只把各列A改成0.90','change only each train availability to0.90'),'1-(1-0.90)**2')
method('sensor',p('感測器偏移校正','Sensor offset calibration'),p('參考標準可辨識偏移；一點校正只能處理固定偏移，斜率誤差須多點標準確認。','A reference reveals offset; one-point correction handles only a constant offset, whereas gain error needs several standards.'),p('參考值10.0、感測器10.8、樣品原讀值14.2，單位一致','reference10.0, sensor10.8 and raw sample14.2 in the same units'),'Ccorrected=Craw-(Cstandard_read-Creference)','14.2-(10.8-10.0)','sensor unit',p('假設偏移固定且量程線性；不代替多點校正與漂移追蹤。','Constant offset and linear range assumed; multi-point calibration and drift tracking remain necessary.'),p('用第二標準獨立驗證校正後殘差並記錄日期與溫度。','Use a second standard to verify corrected residuals independently and record date and temperature.'),p('以同一標準建立又驗證模型會隱藏校正偏差。','Calibrating and validating with the same standard hides bias.'),p('單點校正可以證明整個量程都沒有誤差。','One-point calibration proves the entire range is error-free.'),p('只把樣品原讀值改成16.2','change only raw sample to16.2'),'16.2-(10.8-10.0)')
method('fm',p('食微比與生物量庫存','Food-to-microorganism ratio and inventory'),p('食微比比較每天有機負荷與池內生物固體庫存；BOD、COD、MLSS與MLVSS的基準不得混用。','F/M compares daily organic load with biomass inventory; BOD, COD, MLSS and MLVSS bases must not be mixed.'),p('Q=2000 m³/d、BOD=0.20 kg/m³、V=1000 m³、MLVSS=2 kg/m³','Q=2000 m³/d, BOD=0.20 kg/m³, V=1000 m³ and MLVSS=2 kg/m³'),'F/M=QS/(VX)','2000*0.20/(1000*2)','kg BOD/(kg MLVSS·d)',p('完全混合名目比值，未包含不可生物分解分率與溫度。','Nominal completely mixed ratio; nonbiodegradable fractions and temperature are excluded.'),p('分別量測流量、可生化基質與揮發性固體，再追蹤出水趨勢。','Measure flow, biodegradable substrate and volatile solids separately and track effluent trends.'),p('把惰性固體當活性生物量，會低估真正食微比。','Counting inert solids as active biomass understates the true F/M.'),p('MLSS與活性微生物量完全等同。','MLSS is exactly equal to active microbial mass.'),p('只把MLVSS降成1.5 kg/m³','reduce only MLVSS to1.5 kg/m³'),'2000*0.20/(1000*1.5)')
method('srt',p('污泥齡與固體流失','Sludge age and solids losses'),p('污泥齡等於系統固體庫存除以每天排出的固體；出水帶泥也必須列入，不只剩餘污泥。','SRT equals system solids inventory divided by daily solids losses; effluent carryover counts as well as wasting.'),p('庫存6000 kg、剩餘污泥400 kg/d、出水固體100 kg/d','inventory6000 kg, wasted solids400 kg/d and effluent solids100 kg/d'),'SRT=M/(W+E)','6000/(400+100)','d',p('準穩態且計算邊界一致；忽略日內庫存變化。','Quasi-steady inventory with consistent boundaries; intraday inventory changes are neglected.'),p('以排泥流量乘固體濃度，並同步估出水SS負荷。','Multiply wasting flow by solids concentration and estimate concurrent effluent SS load.'),p('二沉池帶泥會降低污泥齡，不能只調排泥閥猜測。','Clarifier carryover lowers SRT and cannot be diagnosed by wasting settings alone.'),p('不排剩餘污泥就代表沒有生物固體損失。','No intentional wasting means no biomass loss.'),p('只把出水固體提高至200 kg/d','increase only effluent solids to200 kg/d'),'6000/(400+200)')
method('oxygen',p('氧轉移與曝氣功率','Oxygen transfer and aeration power'),p('氧需求與設備供氧能力須用相同工況基準；清水標準效率不能直接當污水池中的效率。','Oxygen demand and equipment transfer capacity require the same conditions; clean-water standard efficiency is not wastewater performance.'),p('假想需氧量480 kg O₂/d、現場修正供氧效率1.5 kg O₂/kWh','hypothetical oxygen demand480 kg O₂/d and field-corrected efficiency1.5 kg O₂/kWh'),'Pavg=O2/(24 SAE)','480/(24*1.5)','kW',p('平均功率示範，未含尖峰、混合需求或備援餘度。','Average-power illustration; peaks, mixing requirements and reserve margin are excluded.'),p('把溶氧、尾氣與電表同步；用一段變負載試驗比較回應。','Synchronize DO, off-gas and power data and compare responses during a changing-load trial.'),p('散氣器堵塞會提高壓力而降低氧轉移，風量增加未必有效。','Clogged diffusers can raise pressure while reducing transfer, so more airflow may be ineffective.'),p('把風量加倍必定使有效供氧加倍。','Doubling airflow necessarily doubles useful oxygen transfer.'),p('只把供氧效率降成1.2 kg O₂/kWh','reduce only transfer efficiency to1.2 kg O₂/kWh'),'480/(24*1.2)')
method('nitrify',p('硝化的氧需求收支','Oxygen balance for nitrification'),p('氨氮氧化成硝酸鹽消耗氧；以氮質量為基準的化學計量與有機碳需氧量應分別列出。','Oxidizing ammonia nitrogen to nitrate consumes oxygen; nitrogen-based stoichiometry and carbonaceous oxygen demand must be listed separately.'),p('假想轉化氨氮量N=30 kg N/d、理論係數4.57 kg O₂/kg N','hypothetical ammonia conversionN=30 kg N/d and theoretical factor4.57 kg O₂/kg N'),'O2=4.57N','4.57*30','kg O₂/d',p('理論完全氧化上界計量，未扣細胞合成或考慮動力學。','Theoretical complete-oxidation stoichiometry; biomass assimilation and kinetics are omitted.'),p('用氨、亞硝酸與硝酸三者的氮收支核對，不只看溶氧。','Check a nitrogen balance using ammonia, nitrite and nitrate rather than DO alone.'),p('低溫或抑制物可使氨突破，即使供氧功率正常。','Cold conditions or inhibitors can cause ammonia breakthrough despite normal aeration power.'),p('有足夠氧就能保證任意溫度下完全硝化。','Enough oxygen guarantees complete nitrification at any temperature.'),p('只把氨氮量改成40 kg N/d','change only ammonia load to40 kg N/d'),'4.57*40')
method('denit',p('反硝化的電子供體需求','Electron-donor demand for denitrification'),p('硝酸鹽還原需要電子供體；理論COD當量僅是起點，可利用碳、細胞產率與溶氧競爭會改變需求。','Nitrate reduction needs an electron donor; theoretical COD equivalence is only a starting point because available carbon, growth and oxygen competition alter demand.'),p('待還原硝酸氮20 kg N/d、理論COD當量2.86 kg/kg N','nitrate nitrogen20 kg N/d and theoretical COD equivalence2.86 kg/kg N'),'CODmin=2.86N','2.86*20','kg COD/d',p('理論電子當量示範，不能當現場加藥劑量。','Theoretical electron-equivalent illustration; not a field chemical dose.'),p('同時看硝酸鹽、可利用COD與溶氧，檢查回流帶氧。','Observe nitrate, available COD and DO together and inspect oxygen introduced by recirculation.'),p('回流氧先消耗基質，會讓只按硝酸鹽估碳量的模型偏低。','Returned oxygen consumes substrate and makes a nitrate-only carbon estimate too low.'),p('總COD全都可以立即供反硝化使用。','All total COD is immediately available for denitrification.'),p('只把硝酸氮改成25 kg N/d','change only nitrate nitrogen to25 kg N/d'),'2.86*25')
method('recycle',p('內回流與水力負荷','Internal recirculation and hydraulic load'),p('回流把反應物帶回前段，也增加管線與反應區通過量；回流率不是污染物去除率。','Recirculation returns reactants upstream while increasing pipe and zone throughput; recycle ratio is not removal efficiency.'),p('進水Q=1000 m³/d、內回流Qr=2000 m³/d','influentQ=1000 m³/d and internal recycleQr=2000 m³/d'),'Qzone=Q+Qr','1000+2000','m³/d',p('只計指定區域的循環水力負荷；外部排放仍須另作平衡。','Hydraulic throughput of one specified zone only; external discharge has a separate balance.'),p('在流路圖分開標示內回流與真正出水，避免重複計量。','Mark internal recycle separately from final effluent to avoid double counting.'),p('把回流水加到整廠外部出水會造成假性水量增加。','Adding recycled flow to external effluent creates fictitious water production.'),p('內回流量越大等於淨產水越多。','Greater internal recycle means more net water production.'),p('只把Qr改成3000 m³/d','change only Qr to3000 m³/d'),'1000+3000')
method('phosphorus',p('磷的轉移與污泥排出','Phosphorus transfer and sludge export'),p('除磷須將磷從水相轉入可排出的固體；生物吸收或化學沉澱不能取代最終排泥。','Phosphorus removal transfers phosphorus into solids that can leave the process; uptake or precipitation does not replace sludge export.'),p('Q=1500 m³/d、進出水磷差ΔP=3 mg/L','Q=1500 m³/d and phosphorus differenceΔP=3 mg/L'),'Mremoved=QΔP/1000','1500*3/1000','kg P/d',p('水相表觀移除，尚需以污泥磷證實去向。','Apparent aqueous removal; sludge phosphorus must confirm the destination.'),p('同時量測溶解態與總磷、污泥含磷率及排泥量。','Measure dissolved and total phosphorus, sludge phosphorus fraction and wasting rate together.'),p('厭氧區帶入硝酸鹽可能干擾生物除磷；先查回流與碳源。','Nitrate entering an anaerobic zone can disrupt biological phosphorus removal; inspect recycle and carbon first.'),p('水相磷下降就表示磷元素已被消滅。','Lower aqueous phosphorus means the element has been destroyed.'),p('只把ΔP改成4 mg/L','change only ΔP to4 mg/L'),'1500*4/1000')
method('coag',p('絮凝試驗與藥量換算','Flocculation trials and dose accounting'),p('混凝使膠體失穩，膠凝讓碰撞形成較易分離的絮體；最佳藥量必須以瓶杯試驗與實際水質確認。','Coagulation destabilizes colloids and flocculation builds separable flocs; dose selection requires jar tests with the actual water.'),p('假想試驗劑量D=12 mg/L、流量Q=5000 m³/d','hypothetical trial doseD=12 mg/L and flowQ=5000 m³/d'),'M=DQ/1000','12*5000/1000','kg/d',p('僅純有效成分質量換算，非建議加藥值；商品濃度須另換算。','Active-ingredient mass conversion only, not a recommended dose; product concentration requires another conversion.'),p('比較多組瓶杯的濁度、pH與沉降；保留未加藥對照。','Compare turbidity, pH and settling across jars and retain an untreated control.'),p('過量藥可能增加污泥或改變pH，不能以越多越好判斷。','Excess dose can increase sludge or alter pH; more is not necessarily better.'),p('所有污水都可以使用同一個固定混凝劑量。','Every wastewater can use one fixed coagulant dose.'),p('只把試驗劑量改成15 mg/L','change only trial dose to15 mg/L'),'15*5000/1000')
method('ozone',p('臭氧轉移與接觸收支','Ozone transfer and contact balance'),p('注入氣體不等於全部進入水中；尾氣與溶解臭氧共同約束實際轉移量。','Injected gas is not entirely transferred to water; off-gas and dissolved ozone constrain actual transferred mass.'),p('假想注入2 kg/h、轉移效率0.75、Q=500 m³/h','hypothetical injection2 kg/h, transfer efficiency0.75 andQ=500 m³/h'),'Dtransferred=1000Minη/Q','1000*2*0.75/500','mg/L',p('質量轉移示範，不是消毒信用或微污染物破壞保證。','Mass-transfer illustration, not disinfection credit or guaranteed micropollutant destruction.'),p('量測尾氣並檢查溴化物與副產物資料，建立目標化合物驗證。','Measure off-gas, review bromide and by-product data and validate the target compound.'),p('水質氧化需求升高會降低目標物可用的氧化能力。','Higher water-matrix demand reduces oxidation available to the target compound.'),p('注入的每公斤臭氧都有效破壞目標污染物。','Every kilogram injected effectively destroys the target pollutant.'),p('只把轉移效率降成0.60','reduce only transfer efficiency to0.60'),'1000*2*0.60/500')

# Sludge, energy and waste-to-energy accounting.
method('sludge',p('乾固體與含水率','Dry solids and moisture'),p('含水污泥總質量由乾固體庫存與固體分率決定；脫水主要移除水而非消滅固體。','Wet sludge mass follows dry-solids inventory and solids fraction; dewatering removes water rather than destroying solids.'),p('乾固體2000 kg/d、固體質量分率0.04','dry solids2000 kg/d and solids mass fraction0.04'),'Mwet=MDS/fDS','2000/0.04','kg/d',p('濃度採質量分率；若體積濃度須先確認密度。','Concentration is a mass fraction; volumetric concentration requires density.'),p('秤重並烘乾配對樣品，分開報告乾量與濕量。','Weigh and dry paired samples, reporting wet and dry mass separately.'),p('把4%寫成4會造成100倍錯誤。','Using4 rather than0.04 produces a hundredfold error.'),p('脫水後濕泥減少的質量全都是污染物被破壞。','All wet-mass reduction during dewatering is destroyed pollution.'),p('只把固體分率提高到0.20','increase only solids fraction to0.20'),'2000/0.20')
method('digestion',p('揮發性固體消化','Volatile-solids digestion'),p('厭氧消化將一部分可降解有機固體轉為氣體；惰性固體保留在消化污泥內。','Anaerobic digestion converts part of degradable volatile solids to gas; inert solids remain in digestate.'),p('進料乾固體3000 kg/d、VS分率0.70、VS破壞率0.50','feed dry solids3000 kg/d, VS fraction0.70 and VS destruction0.50'),'VSdestroyed=MDS fVS η','3000*0.70*0.50','kg VS/d',p('假想穩態質量帳，實際破壞率須以進出料完整固體收支估算。','Hypothetical steady balance; actual destruction needs complete input/output solids accounting.'),p('測進出料TS與VS並檢查貯槽累積，避免以濃度差代替質量差。','Measure feed/digestate TS and VS and inspect storage accumulation; concentration difference is not mass difference.'),p('進料量忽高忽低會讓單日去除率誤導。','Variable feeding makes a single-day destruction estimate misleading.'),p('灰分也能在厭氧消化中全部變成甲烷。','All ash can turn into methane during anaerobic digestion.'),p('只把VS破壞率改成0.60','change only VS destruction to0.60'),'3000*0.70*0.60')
method('methane',p('COD與甲烷理論潛力','COD and theoretical methane potential'),p('電子當量可把被轉化COD連結到甲烷的理論體積；細胞合成、溶解甲烷與洩漏使實收量較低。','Electron equivalence links converted COD to theoretical methane volume; growth, dissolved methane and leaks reduce collected gas.'),p('已轉化COD=1000 kg/d、理論上限0.35 Nm³ CH₄/kg COD','converted COD=1000 kg/d and theoretical upper factor0.35 Nm³ CH₄/kg COD'),'VCH4=0.35 CODconverted','0.35*1000','Nm³ CH₄/d',p('Nm³採0°C、1atm基準；上限計量而非廠商產氣保證。','Nm³ uses0°C and1atm; stoichiometric upper bound, not a supplier guarantee.'),p('將氣量修正到同一溫壓，量測甲烷分率與溶解排出。','Normalize gas volume to the same temperature/pressure and measure methane fraction and dissolved losses.'),p('把總沼氣量當純甲烷量會高估可用熱值。','Treating total biogas as pure methane overestimates energy.'),p('所有COD移除都會轉為可收集甲烷。','Every unit of removed COD becomes collected methane.'),p('只把已轉化COD改成800 kg/d','change only converted COD to800 kg/d'),'0.35*800')
method('chp',p('沼氣熱電聯產','Biogas combined heat and power'),p('甲烷化學能在機組中分成電、可用熱與損失；發電效率不能與總利用效率混稱。','Methane energy splits into electricity, usable heat and losses; electrical efficiency differs from total utilization.'),p('甲烷500 Nm³/d、低位熱值9.94 kWh/Nm³、發電效率0.35','methane500 Nm³/d, lower heating value9.94 kWh/Nm³ and electrical efficiency0.35'),'Eel=V LHV ηel','500*9.94*0.35','kWh/d',p('假想機組固定效率；未扣輔機電力，熱能另計。','Fixed hypothetical efficiency; auxiliaries are not deducted and heat is separate.'),p('以燃氣能量帳對照總發電、輸出電與供熱三個表。','Compare fuel energy with gross electricity, exported electricity and delivered heat meters.'),p('把發電與廠內耗電相加當外售量會重複計數。','Adding generation and internal consumption as exports double counts energy.'),p('熱電聯產可同時把全部燃料能量變成電又變成熱。','CHP can convert all fuel energy separately into both electricity and heat.'),p('只把發電效率改成0.30','change only electrical efficiency to0.30'),'500*9.94*0.30')
method('heat',p('污泥加熱與熱回收','Sludge heating and heat recovery'),p('顯熱需求取決於質量、比熱與溫差；預熱回收降低外加熱但不改變最終溫度目標的熱力學收支。','Sensible heat depends on mass, heat capacity and temperature difference; recovery reduces external heat without changing the thermodynamic duty.'),p('m=10000 kg/d、cp=4.18 kJ/(kg·K)、ΔT=20 K','m=10000 kg/d, cp=4.18 kJ/(kg·K) andΔT=20 K'),'Qheat=m cp ΔT/3600','10000*4.18*20/3600','kWh/d',p('以水近似污泥比熱；不含相變與槽壁損失。','Water-like heat capacity assumed; phase change and wall losses excluded.'),p('量測進出溫度及流量，區分換熱回收與燃料投入。','Measure inlet/outlet temperatures and flow, distinguishing recovered heat from fuel input.'),p('換熱器結垢使熱端溫度上升但冷端升溫不足。','Fouling can raise hot-side temperature while providing insufficient cold-side heating.'),p('有熱回收就不再需要能量平衡。','Heat recovery removes the need for an energy balance.'),p('只把溫差改成15 K','change only temperature difference to15 K'),'10000*4.18*15/3600')
method('netenergy',p('淨電力與廠用負載','Net electricity and auxiliary loads'),p('能源自給須以同一邊界比較可用發電與所有廠用電；年度淨額不代表每小時離網。','Energy self-sufficiency compares usable generation and all internal loads within one boundary; an annual net balance does not prove hourly islanded operation.'),p('發電5000 kWh/d、曝氣2800、泵600、其他400 kWh/d','generation5000 kWh/d, aeration2800, pumping600 and other loads400 kWh/d'),'Enet=Eg-Ea-Ep-Eother','5000-2800-600-400','kWh/d',p('示範日帳，未含備援燃料與尖峰電力容量。','Illustrative daily ledger; reserve fuel and peak power capacity are omitted.'),p('核對發電、購電與售電表，在相同邊界做全年帳。','Reconcile generation, imports and exports within the same boundary over a year.'),p('漏掉臭氣處理與污泥設備用電會誇大淨盈餘。','Omitting odor and sludge equipment overstates net surplus.'),p('年發電量大於用電就證明完全不用外電。','Annual generation above demand proves no grid imports are needed.'),p('只把曝氣用電提高到3500 kWh/d','increase only aeration demand to3500 kWh/d'),'5000-3500-600-400')
method('thermal',p('垃圾熱值與熱輸入','Waste heating value and heat input'),p('熱輸入由垃圾質量流率及低位熱值決定；水分、惰性物與可燃成分會使同噸數產生不同熱量。','Heat input depends on waste mass flow and lower heating value; moisture, inert material and combustibles change energy at the same tonnage.'),p('m=10 t/h、LHV=8 MJ/kg','m=10 t/h andLHV=8 MJ/kg'),'Pthermal=m LHV/3.6','10*8/3.6','MW',p('熱輸入示範，不是爐體操作限值或爐排設計。','Heat-input example, not a furnace operating limit or grate design.'),p('以代表性混合樣估熱值，核對秤重與蒸汽生成趨勢。','Estimate heating value from representative composite samples and compare weighbridge and steam trends.'),p('高含水垃圾可使熱值下降；只依噸數預測發電會偏差。','Wet waste reduces heating value; tonnage alone mispredicts power.'),p('相同垃圾噸數必定產生相同熱量。','Equal waste tonnage always provides equal heat.'),p('只把LHV改成6 MJ/kg','change only LHV to6 MJ/kg'),'10*6/3.6')
method('steam',p('蒸汽焓差與鍋爐熱量','Steam enthalpy rise and boiler duty'),p('鍋爐將水的焓提高到蒸汽狀態；應用焓差而不是單靠出口溫度計算熱量。','A boiler raises feedwater enthalpy to steam conditions; use enthalpy difference rather than outlet temperature alone.'),p('蒸汽流率5 kg/s、蒸汽與給水焓差2400 kJ/kg','steam flow5 kg/s and steam-to-feedwater enthalpy rise2400 kJ/kg'),'Psteam=m Δh/1000','5*2400/1000','MW',p('假想查表焓值已給定；未含排污、蒸汽品質與非穩態。','Hypothetical tabulated enthalpy difference supplied; blowdown, quality and transients excluded.'),p('使用同時壓力、溫度與流量，從蒸汽表核對焓狀態。','Use concurrent pressure, temperature and flow and check enthalpy states in steam tables.'),p('將飽和與過熱蒸汽混用會算錯能量。','Mixing saturated and superheated states gives an incorrect energy balance.'),p('蒸汽溫度相同就表示焓與功率也相同。','Equal steam temperature implies equal enthalpy and power.'),p('只把蒸汽流率改成4 kg/s','change only steam flow to4 kg/s'),'4*2400/1000')
method('efficiency',p('淨發電效率','Net electrical efficiency'),p('效率必須明確寫出有用輸出與能量輸入；電效率與含供熱的總效率不可直接比較。','Efficiency needs explicit useful-output and energy-input definitions; electrical and heat-inclusive efficiencies are not directly comparable.'),p('熱輸入30 MW、總發電8 MW、廠用1 MW','thermal input30 MW, gross electricity8 MW and auxiliaries1 MW'),'ηnet=100(Pgross-Paux)/Pfuel','100*(8-1)/30','%',p('穩態低位熱值基準；不含供熱信用與生命週期排放。','Steady lower-heating-value basis; heat credit and life-cycle emissions excluded.'),p('以共同時窗核對燃料熱值、總發電與廠用負載。','Reconcile fuel heating value, gross generation and auxiliaries over one interval.'),p('用高位熱值輸入搭配低位熱值比較值會錯置效率。','Mixing higher- and lower-heating-value bases distorts comparisons.'),p('總發電量就是淨輸出電量。','Gross generation equals net electricity output.'),p('只把廠用改成1.5 MW','change only auxiliaries to1.5 MW'),'100*(8-1.5)/30')
method('stack',p('煙氣濃度與排放質量','Flue-gas concentration and emission mass'),p('排放質量率取決於濃度乘氣體體積流率；濕乾基、氧校正與標準狀態必須一致。','Emission mass rate is concentration times gas flow; wet/dry basis, oxygen correction and standard conditions must agree.'),p('C=20 mg/Nm³、乾基Q=100000 Nm³/h，兩者同基準','C=20 mg/Nm³ and dryQ=100000 Nm³/h on the same basis'),'M=CQ/1000000','20*100000/1000000','kg/h',p('同基準的示範排放帳；不是任何地區法定排放限值。','Same-basis illustrative emissions ledger, not a statutory limit.'),p('同步氣量、濃度與氧含量，查校正狀態及無效資料標記。','Synchronize gas flow, concentration and oxygen while checking calibration and invalid-data flags.'),p('稀釋煙氣可降濃度卻不降污染質量。','Diluting flue gas lowers concentration without lowering pollutant mass.'),p('只要濃度下降，排放總質量必定下降。','Lower concentration necessarily means lower emitted mass.'),p('只把氣量改成120000 Nm³/h','change only gas flow to120000 Nm³/h'),'20*120000/1000000')
method('bag',p('袋濾器氣布比','Fabric-filter air-to-cloth ratio'),p('氣布比是體積流量除以濾布面積；積塵層能提高捕集但也增加壓差。','Air-to-cloth ratio is gas flow divided by fabric area; a dust cake improves capture while increasing pressure drop.'),p('實際氣量Q=60000 m³/h、有效濾布A=1000 m²','actual gasQ=60000 m³/h and active clothA=1000 m²'),'v=Q/(60A)','60000/(60*1000)','m/min',p('採實際溫度氣量，不可直接把Nm³當m³；非設備選型限值。','Use actual-temperature gas volume, not Nm³ directly; not a filter sizing limit.'),p('按隔室紀錄壓差、脈衝與排放趨勢，查破袋或離線面積。','Log compartment pressure drop, pulses and emissions and check broken bags or offline area.'),p('濾袋破損可能讓壓差下降同時排放上升。','A torn bag can lower pressure drop while increasing emissions.'),p('壓差越低就保證除塵越好。','Lower pressure drop guarantees better dust capture.'),p('只把有效濾布降成800 m²','reduce only active cloth to800 m²'),'60000/(60*800)')
method('ash',p('灰渣分流與質量帳','Ash-stream separation and mass balance'),p('底渣與飛灰來源、污染物分布及處置需求不同，必須分流記錄；金屬回收不等於殘渣自動合格。','Bottom ash and fly ash differ in origin, contaminant distribution and management needs; keep separate ledgers, and metal recovery does not automatically certify residues.'),p('垃圾100 t/d、假想底渣分率0.20、飛灰分率0.03','waste100 t/d, assumed bottom-ash fraction0.20 and fly-ash fraction0.03'),'Mash=Mw(fbottom+ffly)','100*(0.20+0.03)','t/d',p('假想濕乾基一致的分率，非實際廠產率；須另考慮添加劑與水分。','Hypothetical consistent moisture basis, not actual plant yield; additives and moisture require separate entries.'),p('各物流秤重並採代表性樣品，維持處置聯單與品質資料。','Weigh each stream, take representative samples and retain disposal and quality records.'),p('混合底渣飛灰會失去追蹤與適切處理的依據。','Mixing bottom and fly ash loses traceability and treatment distinctions.'),p('焚化後所有固體都消失，不需後續管理。','Incineration eliminates all solids and subsequent management.'),p('只把垃圾量改成120 t/d','change only waste to120 t/d'),'120*(0.20+0.03)')

# Urban water, ecological restoration, and contaminated-land reasoning.
method('runoff',p('集水面積與逕流量','Catchment area and runoff volume'),p('降雨量乘面積提供總水量，以逕流係數近似扣除入滲與其他損失；該係數隨土壤與前期濕度而變。','Rain depth times area gives total water; a runoff coefficient approximates infiltration and other losses and varies with soil and antecedent moisture.'),p('雨深P=30 mm、集水面積A=10000 m²、C=0.75','rainP=30 mm, catchmentA=10000 m² andC=0.75'),'V=CPA/1000','0.75*30*10000/1000','m³',p('事件總量近似，不能推得尖峰流率或管線容量。','Event-volume approximation; does not predict peak flow or pipe capacity.'),p('畫屋頂、路面與綠地分區，分別加權C並核對雨量站。','Map roofs, pavement and vegetation, weight C separately and check rainfall data.'),p('把mm直接乘m²而未除1000會造成千倍錯誤。','Multiplying mm bym² without dividing by1000 gives a thousandfold error.'),p('總雨量相同就保證尖峰淹水風險相同。','Equal storm totals guarantee equal peak flood risk.'),p('只把C降成0.50','reduce only C to0.50'),'0.50*30*10000/1000')
method('infiltration',p('入滲容量與堵塞','Infiltration capacity and clogging'),p('表觀入滲率乘有效面積估算短時入滲能力；降雨前土壤濕度與細粒堵塞會改變它。','Apparent infiltration rate times active area estimates short-duration intake; antecedent moisture and fine-particle clogging change it.'),p('入滲率f=10 mm/h、面積A=500 m²','infiltrationf=10 mm/h and areaA=500 m²'),'Qinf=fA/1000','10*500/1000','m³/h',p('短時均勻近似，未包括地下水抬升與非飽和動力學。','Short-duration uniform approximation; groundwater rise and unsaturated dynamics excluded.'),p('多位置入滲試驗並記錄前期濕度，檢查溢流路徑。','Test infiltration at several positions, record antecedent moisture and inspect overflow routes.'),p('表面細砂堵塞會讓原設計入滲值失效。','Fine-sediment surface clogging invalidates the original infiltration estimate.'),p('入滲設施永遠不會飽和，也不需要溢流。','An infiltration facility never saturates and needs no overflow.'),p('只把f降成4 mm/h','reduce only f to4 mm/h'),'4*500/1000')
method('drawdown',p('退水時間與恢復使用','Drawdown time and return to use'),p('暫存水需在下次事件前排空並確認使用條件；退水時間由可用排水流量決定。','Stored water needs drawdown before the next event and a check before public use; available discharge governs drawdown time.'),p('待排水V=180 m³、定流量Q=15 m³/h','stored waterV=180 m³ and constant dischargeQ=15 m³/h'),'t=V/Q','180/15','h',p('固定出流示範；孔口出流隨水頭下降須積分計算。','Constant-flow illustration; orifice discharge declining with head needs integration.'),p('以水位記錄核對退水曲線，巡查積水與污物後才恢復場地。','Check the drawdown curve against level data and inspect standing water and debris before reopening.'),p('出水口被落葉堵塞會延長不可用時間。','Leaf-blocked outlets lengthen unavailable time.'),p('雨停後場地一定立刻可安全使用。','A space is necessarily ready for safe use immediately when rain stops.'),p('只把Q降成10 m³/h','reduce only Q to10 m³/h'),'180/10')
method('shear',p('河床剪應力與岸坡材料','Bed shear and bank materials'),p('均勻流平均剪應力約為ρgRS；植被與岸坡材料的抗蝕能力應與局部流況一起檢核。','Mean boundary shear in uniform flow is aboutρgRS; erosion resistance of vegetation and banks needs checking against local hydraulics.'),p('ρ=1000 kg/m³、R=0.6 m、S=0.001','ρ=1000 kg/m³, R=0.6 m andS=0.001'),'τ=ρgRS','1000*9.81*0.6*0.001','Pa',p('斷面平均值，不含彎道、橋墩與局部湍流尖峰。','Section mean; bends, piers and local turbulence peaks excluded.'),p('比較洪後沖淤剖面與植被存活，不只採用一張乾季照片。','Compare post-flood erosion profiles and plant survival rather than one dry-season photograph.'),p('彎道外側局部沖刷可遠高於平均值。','Outer-bend local scour can greatly exceed the mean.'),p('全段平均剪應力低就證明每處河岸都不會侵蝕。','Low reach-average shear proves that no bank location can erode.'),p('只把S增加到0.002','increase only S to0.002'),'1000*9.81*0.6*0.002')
method('heatshade',p('遮蔭與表面熱收支','Shade and surface heat balance'),p('遮蔭減少短波吸收，但人體熱感還受到風、長波輻射與濕度影響。','Shade reduces absorbed shortwave radiation, while human thermal sensation also depends on wind, longwave radiation and humidity.'),p('面積100 m²、入射600 W/m²、吸收率0.70、遮蔭減少入射0.60','area100 m², irradiance600 W/m², absorptivity0.70 and shade reduction0.60'),'ΔP=A I α fshade/1000','100*600*0.70*0.60/1000','kW',p('單一表面瞬時短波示範，不直接預測氣溫或體感溫度。','Instantaneous shortwave balance of one surface; not an air or perceived-temperature prediction.'),p('同時量測陰陽面表面溫度、輻射與風，採相同時段對照。','Measure shaded/unshaded surface temperature, radiation and wind concurrently.'),p('只用紅外線表面溫度宣稱人體降溫會混淆指標。','Claiming human cooling from infrared surface temperature alone confuses indicators.'),p('路面降溫數字可以直接當作人體感覺降溫。','Pavement cooling equals perceived human cooling.'),p('只把遮蔭比例提高至0.80','increase only shade reduction to0.80'),'100*600*0.70*0.80/1000')
method('ecology',p('棲地樣區與多樣性指標','Habitat plots and diversity indicators'),p('Simpson多樣性以物種比例衡量優勢程度；指標增加不等於所有原生物種都恢復。','Simpson diversity measures dominance through species proportions; a larger index does not prove recovery of every native species.'),p('四類生物比例0.4、0.3、0.2、0.1','four taxon proportions0.4,0.3,0.2,0.1'),'D=1-Σpi²','1-(0.4**2+0.3**2+0.2**2+0.1**2)','index',p('相同採樣方法與努力量；不替代保育物種與外來種調查。','Same sampling method and effort; not a replacement for protected- and invasive-species surveys.'),p('固定樣區、季節與採樣時長，另記棲地連續性與外來種。','Fix plots, season and effort and separately record connectivity and invasive species.'),p('採樣努力量增加會製造看似改善，須對照基線。','Greater sampling effort can mimic improvement; compare with the baseline.'),p('看到更多物種就可以忽略是否為入侵物種。','More observed species makes invasive status irrelevant.'),p('只把分布改成四類各0.25','change only proportions to four equal0.25'),'1-4*0.25**2')
method('paired',p('前後與對照地點比較','Before-after and control comparison'),p('干預前後差異還可能包含天氣與背景趨勢；前後—對照差分可分離共同變化但仍須檢查可比性。','Before-after changes include weather and background trends; difference-in-differences removes common changes but still needs comparable sites.'),p('處理地由30降至27，對照地由29降至28，同一指標','treated site30 to27 and control site29 to28 for the same indicator'),'effect=(Tafter-Tbefore)-(Cafter-Cbefore)','(27-30)-(28-29)','indicator unit',p('假設共同背景趨勢；不是隨機試驗或完全因果證明。','Common background trend assumed; not a randomized trial or complete causal proof.'),p('採同期多日資料並檢查前期趨勢，不選只對結果有利的一天。','Use simultaneous multi-day data, inspect pre-trends and avoid selecting a favorable day.'),p('處理地同時換交通流量會讓單一干預歸因失真。','Concurrent traffic changes at the treated site confound attribution.'),p('前後改變全都必定由這一項工程造成。','Every before-after change must be caused by this project.'),p('只把對照地事後值改成27','change only control-after to27'),'(27-30)-(27-29)')
method('soil',p('土壤污染質量與範圍','Soil contaminant mass and extent'),p('污染濃度乘乾土質量估計污染庫存；空間異質性與土壤體積密度會控制不確定度。','Concentration times dry-soil mass estimates contaminant inventory; spatial heterogeneity and bulk density govern uncertainty.'),p('乾土1000 t、代表性濃度200 mg/kg','dry soil1000 t and representative concentration200 mg/kg'),'Mcontaminant=Msoil C/1000','1000*200/1000','kg',p('代表性平均濃度假設，不能替代熱點與暴露途徑調查。','Representative mean concentration assumed; hotspots and exposure pathways need separate investigation.'),p('建立採樣網格與深度分層，查檢出限、重複樣及空白樣。','Create a sampling grid and depth strata, checking detection limits, duplicates and blanks.'),p('以乾淨區稀釋平均濃度會掩蓋局部熱點。','Diluting the mean with clean areas hides hotspots.'),p('全場平均濃度低就代表每一處都安全。','A low site mean proves every location is safe.'),p('只把土壤量改成1500 t','change only soil mass to1500 t'),'1500*200/1000')
method('soilwash',p('洗土分級與污染濃縮','Soil washing and contaminant concentration'),p('污染若偏附細粒，分級可使粗粒再利用而把污染集中到細泥；這是分離而非破壞。','When contamination associates with fines, separation can recover coarse soil while concentrating contamination in sludge; this separates rather than destroys it.'),p('總污染100 kg、80%進入20 t乾細泥','total contaminant100 kg with80% entering20 t dry fines'),'Cfines=Mcont f/(Mfines*1000)*1e6','100*0.80/(20*1000)*1e6','mg/kg',p('假想分配率；需確認溶出、水相與粗粒殘留才能封閉收支。','Hypothetical partition; dissolved mass and coarse residues must also close the balance.'),p('秤各粒級並分析細泥、粗土與循環水，檢核三相去向。','Weigh size fractions and analyze fines, coarse soil and washwater to check all destinations.'),p('只測粗土而漏細泥會誤報整治量與處置負擔。','Testing coarse soil alone misreports remediation and disposal burdens.'),p('洗土後粗粒變乾淨就代表污染元素消失。','Clean coarse soil after washing means the contaminant element disappeared.'),p('只把細泥質量改成25 t','change only fines mass to25 t'),'100*0.80/(25*1000)*1e6')
method('landfillwater',p('覆蓋層水量平衡','Cover-system water balance'),p('降雨被分成逕流、蒸散、儲水變化與向下滲漏；綠色覆蓋並不表示滲漏已受控制。','Rain partitions into runoff, evapotranspiration, storage change and percolation; green cover does not prove leakage control.'),p('P=100、R=30、ET=40、ΔS=10 mm，同一期間','P=100, R=30, ET=40 andΔS=10 mm over the same period'),'Perc=P-R-ET-ΔS','100-30-40-10','mm',p('面積平均帳，未表示襯層缺陷造成的局部滲漏。','Area-average ledger; localized leakage through liner defects is not represented.'),p('比較氣象、水位與滲出水流量，檢查季節儲水變化。','Compare weather, water levels and leachate flow and inspect seasonal storage.'),p('沉陷破壞排水坡度會造成積水與局部滲漏。','Settlement can reverse drainage slopes, causing ponding and local leakage.'),p('覆土長滿植物就表示掩埋場已無環境風險。','Vegetated cover means the landfill has no environmental risk.'),p('只把逕流R改成20 mm','change only runoffR to20 mm'),'100-20-40-10')
method('gas',p('掩埋氣體收集與逸散','Landfill-gas capture and fugitive loss'),p('抽取井收集的氣體只占產氣一部分；必須區分產生、收集、氧化與逸散。','Collection wells capture only part of generated gas; distinguish generation, collection, oxidation and fugitive emissions.'),p('假想甲烷產生1000 Nm³/d、收集率0.70','hypothetical methane generation1000 Nm³/d and capture fraction0.70'),'Vuncaptured=Vgenerated(1-fcapture)','1000*(1-0.70)','Nm³/d',p('未收集不全等於排到大氣，覆土氧化需另外估計。','Uncaptured gas is not all atmospheric emission; cover oxidation needs separate estimation.'),p('結合井場流量、表面巡測與覆層資料，不只看總管抽氣量。','Combine well-field flow, surface surveys and cover information rather than header flow alone.'),p('過度抽氣引入空氣可能改變氣體品質與火災風險。','Excess extraction can draw in air, changing gas quality and fire risk.'),p('收集總管沒有讀到甲烷就表示地下沒有甲烷。','No methane reading in the collection header means none exists underground.'),p('只把收集率改成0.80','change only capture fraction to0.80'),'1000*(1-0.80)')
method('settlement',p('差異沉陷與地形坡度','Differential settlement and surface slope'),p('兩點差異沉陷改變排水坡度，影響覆層完整性、管線與公共設施；平均沉陷不足以判讀。','Differential settlement changes drainage grade and stresses covers, pipes and public facilities; mean settlement is insufficient.'),p('兩點距離L=20 m、差異沉陷Δs=0.10 m','point spacingL=20 m and differential settlementΔs=0.10 m'),'Δslope=100Δs/L','100*0.10/20','%',p('小變形幾何示範，不是邊坡穩定或地基承載分析。','Small-deformation geometry, not slope stability or foundation capacity analysis.'),p('設置穩定外部基準點，重複測量並查局部裂縫與積水。','Use a stable external datum, repeat surveys and inspect cracks and ponding.'),p('基準點也沉陷會使全部測點看似不動。','A settling datum can make all monitored points appear stationary.'),p('只測一個點的高程就能判斷整個覆蓋層完整。','One point elevation proves the whole cover is intact.'),p('只把差異沉陷改成0.20 m','change only differential settlement to0.20 m'),'100*0.20/20')
method('habitat',p('生態廊道與可用棲地','Ecological corridors and usable habitat'),p('綠地面積與真正連通的可用棲地不同；硬質障礙、照明與維護方式影響動植物通行。','Green area differs from connected usable habitat; hard barriers, lighting and maintenance affect movement.'),p('廊道長800 m、平均有效寬度12 m','corridor length800 m and mean effective width12 m'),'A=Lw','800*12','m²',p('幾何面積近似，不是物種存活率或生態服務價值。','Geometric-area approximation, not survival probability or ecosystem-service valuation.'),p('在地圖標斷點，搭配定點觀察確認指定物種是否實際使用。','Map breaks and use fixed observations to verify use by specified species.'),p('廊道被道路切斷時，相同面積仍可能失去連通。','A road break can destroy connectivity despite unchanged area.'),p('只要綠地面積增加，所有物種都會受益。','More green area benefits every species.'),p('只把有效寬度減成8 m','reduce only effective width to8 m'),'800*8')

