course(401,p('從膜分離到回用需求的多重障壁','Multiple barriers from membrane separation to reuse demand'),p('以新生水為觀察案例，學徒扮演水質工程師，沿進水、膜列、消毒、儲水與需求端追蹤水和污染物。','Using NEWater as the reference, the learner acts as a water-quality engineer following water and contaminants through feed, membrane trains, disinfection, storage and demand.'),p('PUB的新生水流程以膜處理和紫外線建立多重障壁；本課以公開流程重建教學模型，不複製任何廠的操作配方。','PUB describes a multi-barrier process using membrane treatment and ultraviolet light; this lesson reconstructs an educational model without copying an operating recipe.'),'load mf tmp recovery rejection brine roenergy uv log blend',contexts(('二級處理出水採樣站','secondary-effluent sampling station'),('前處理膜列','pretreatment membrane train'),('壓差與溫度儀表盤','pressure and temperature panel'),('逆滲透產濃水分流','RO permeate/concentrate split'),('產水導電度檢驗台','permeate conductivity bench'),('濃水去向管線','concentrate disposal route'),('高壓泵電力表','high-pressure pump energy meter'),('紫外線接觸區','UV exposure zone'),('障壁驗證紀錄','barrier-validation record'),('工業回用需求端','industrial reuse demand')),'reuse newaterstory nutrient',SG,['進水界定~Feed boundary','前處理膜~Pretreatment membrane','逆滲透~Reverse osmosis','紫外線~Ultraviolet','品質監測~Quality monitoring','回用需求~Reuse demand'])
course(402,p('重力深隧道、調蓄與集中處理介面','Gravity tunnels, storage and centralized treatment interfaces'),p('以DTSS觀察集中污水系統，先分清幹管輸送與末端處理，再檢查尖峰、沉積、提升與備援的耦合。','Use DTSS to examine centralized sewerage, distinguishing conveyance from treatment before checking peaks, sediment, lifting and redundancy.'),p('PUB公開資料將DTSS描述為深隧道、連接污水管與水再生廠的整合系統；第一階段於2008年完成。','PUB describes DTSS as an integrated system of deep tunnels, link sewers and water reclamation plants; its first phase was completed in2008.'),'load peak velocity manning storage pump hrt sludge sensor availability',contexts(('支線污染與流量入口','link-sewer load entry'),('集中系統尖峰邊界','centralized peak-flow boundary'),('深隧道有效斷面','deep-tunnel clear section'),('重力坡度與襯面','gravity slope and lining'),('暫態調蓄空間','transient storage space'),('末端提升至處理廠','terminal lift to treatment'),('長距離輸送時間','long-distance conveyance time'),('沉積固體維護帳','deposited-solids maintenance ledger'),('水位與流量同步','level/flow synchronization'),('共享提升與電源介面','shared lift and power interfaces')),'dtss dtsspub',SG,['支線~Link sewers','落差井~Drop shafts','深隧道~Deep tunnel','提升~Lifting','水再生廠~Reclamation plant','回用與放流~Reuse and discharge'])
course(403,p('高級處理與地下水補注的連續證據','Evidence across advanced treatment and aquifer recharge'),p('GWRS將膜處理與UV/H₂O₂後的水送至補注系統。本課追蹤水質障壁、補注能力與地下水傳輸，避免把地下水視為無限儲槽。','GWRS sends membrane- and UV/H₂O₂-treated water to recharge systems. This lesson follows barriers, recharge capacity and aquifer transport without assuming unlimited groundwater storage.'),p('OCWD公開流程列出微濾、逆滲透和紫外線搭配過氧化氫，並以入滲池及注入方式補充地下水。','OCWD documents microfiltration, reverse osmosis and ultraviolet light with hydrogen peroxide, followed by basin and well recharge.'),'mf recovery rejection brine uv log darcy travel pump sensor',contexts(('微濾前處理','microfiltration pretreatment'),('逆滲透水量分流','RO water split'),('產水溶質驗證','permeate-solute verification'),('濃水獨立處置帳','separate concentrate ledger'),('UV/AOP光量子模型','UV/AOP fluence submodel'),('多重障壁證據','multiple-barrier evidence'),('補注池入滲介面','recharge-basin interface'),('觀測井與含水層傳輸','monitoring wells and aquifer transport'),('輸送與注入能耗','conveyance and injection energy'),('配對井水與儀表樣品','paired well-water and sensor samples')),'gwrs gwrsqa',('芳泉谷代表點','Fountain Valley reference point','美國','United States',33.71,-117.95),['二級出水~Secondary effluent','微濾~Microfiltration','逆滲透~Reverse osmosis','UV/AOP~UV/AOP','補注~Recharge','含水層監測~Aquifer monitoring'])
course(404,p('合流溢流截流與隧道系統容量','Combined-sewer interception and tunnel capacity'),p('從溢流口走到豎井、隧道與後端處理，學習為何截流、調蓄和抽送必須同時檢查；隧道本身不是污水淨化反應器。','Follow overflow interception through shafts, tunnel and downstream treatment, checking capture, storage and pumping together; the tunnel is not itself a purification reactor.'),p('Tideway公開資訊指出新隧道連接既有Lee Tunnel與污水處理網路，豎井將截流污水帶入主隧道。','Tideway describes connection to the existing Lee Tunnel and sewer-treatment network, with shafts channeling intercepted flows into the main tunnel.'),'runoff peak storage velocity manning hrt pump load sensor availability',contexts(('合流區雨水入口','combined-catchment storm entry'),('溢流口尖峰歷線','overflow peak hydrograph'),('主隧道暫存','main-tunnel storage'),('截流構造通水','interception flow section'),('隧道重力輸送','gravity tunnel conveyance'),('污水滯留時間','sewage residence time'),('雨後抽送恢復容量','post-storm pumping recovery'),('送往處理廠污染帳','load delivered to treatment'),('沿線液位同步','distributed level synchronization'),('截流系統備援','interception-system redundancy')),'tideway thames',('倫敦代表點','London reference point','英國','United Kingdom',51.51,-0.10),['合流下水道~Combined sewer','截流口~Interception','豎井~Shaft','主隧道~Main tunnel','抽送~Pumping','污水處理~Treatment'])
course(405,p('隧道與大型水庫的事件調蓄','Event storage in tunnels and reservoirs'),p('TARP展示如何把暴雨期間的混合水暫存，於能力允許時送回處理。學徒需建立前一場雨尚未排空的連續事件情境。','TARP illustrates storing combined flows during storms and returning them for treatment when capacity permits. The learner must model consecutive events before storage has emptied.'),p('MWRD將TARP描述為深大直徑隧道與水庫系統，目的包括減少淹水與合流溢流污染。','MWRD describes TARP as deep large-diameter tunnels and reservoirs intended to reduce flooding and combined-sewer overflow pollution.'),'runoff peak storage drawdown pump load clarify sensor availability paired',contexts(('服務集水區降雨','service-catchment rainfall'),('截流系統瓶頸','interceptor bottleneck'),('隧道水庫共同儲量','combined tunnel/reservoir storage'),('連續暴雨間退水','interstorm drawdown'),('回送污水處理','return pumping to treatment'),('調蓄污染質量','stored pollutant mass'),('庫內沉積觀察','reservoir sedimentation observation'),('庫水位及雨量對時','reservoir/rainfall timing'),('暴雨中泵組退出','pump unavailability during storms'),('工程前後水質對照','before-after water-quality comparison')),'tarp tarpreports',('芝加哥代表點','Chicago reference point','美國','United States',41.88,-87.63),['暴雨入流~Storm inflow','截流~Interception','深隧道~Deep tunnel','水庫~Reservoir','回送~Return flow','處理廠~Treatment plant'])
course(406,p('污泥碳分配與能源自給邊界','Sludge-carbon allocation and energy-self-sufficiency boundary'),p('以維也納E_OS為案例，將水線需氧與污泥產氣放在同一能量帳；先看出水要求，再比較有機物進曝氣或消化的不同去向。','Using Vienna E_OS, put liquid-line oxygen demand and sludge gas recovery in one energy ledger; meet effluent needs before comparing carbon sent to aeration or digestion.'),p('ebswien及其研究文獻以污泥處理、消化氣及能量整合說明污水廠能源轉型；教學算例不代表其實測績效。','ebswien and project research describe energy transformation through sludge treatment, biogas and integration; the teaching examples are not measured plant performance.'),'load clarify sludge digestion methane heat chp oxygen netenergy availability',contexts(('進廠有機碳入口','incoming organic-carbon boundary'),('初沉碳捕集','primary carbon capture'),('濃縮污泥輸送','thickened-sludge transfer'),('消化槽固體收支','digester solids balance'),('沼氣理論與實收','theoretical and collected gas'),('污泥換熱器','sludge heat exchanger'),('沼氣熱電機組','biogas CHP unit'),('水線曝氣需求','liquid-line aeration demand'),('全廠電力邊界','whole-plant electricity boundary'),('能量系統停機情境','energy-system outage scenario')),'vienna viennaresearch nutrient',('維也納代表點','Vienna reference point','奧地利','Austria',48.21,16.37),['污水~Wastewater','固體分離~Solids capture','消化~Digestion','沼氣~Biogas','熱電聯產~CHP','能源帳~Energy ledger'])
course(407,p('焚化熱電、污染控制與城市共存','Waste-to-energy, pollution control and urban coexistence'),p('把Amager Bakke拆成進料、燃燒、蒸汽、熱電、煙氣及灰渣六條證據鏈；公共空間外觀與工廠環境績效分開驗證。','Divide Amager Bakke into evidence chains for feed, combustion, steam, energy, flue gas and ash; assess public-space appearance separately from environmental performance.'),p('ARC公開流程顯示垃圾能源回收與多段煙氣處理，排放監測位於煙囪前；本課不把能源回收等同零排放。','ARC documents waste-energy recovery, staged flue-gas treatment and monitoring before the stack; energy recovery is not treated as zero emissions.'),'load thermal steam efficiency heat bag stack ash netenergy paired',contexts(('垃圾進料質量帳','waste-feed mass ledger'),('爐排熱輸入','grate heat input'),('餘熱鍋爐','heat-recovery boiler'),('汽輪機淨發電','net turbine electricity'),('區域供熱介面','district-heating interface'),('煙氣濾布系統','flue-gas fabric system'),('煙囪排放質量','stack emission mass'),('底渣飛灰分流','bottom/fly ash separation'),('廠用與輸出能量','auxiliaries and exports'),('市民環境成效觀察','community environmental outcome')),'arc wte',('哥本哈根代表點','Copenhagen reference point','丹麥','Denmark',55.68,12.57),['垃圾~Waste','爐排~Grate','鍋爐~Boiler','熱電~Heat and power','煙氣處理~Flue-gas treatment','灰渣管理~Ash management'])
course(408,p('A₂O、生物膜過濾與非飲用回用','A₂O, biofilm filtration and nonpotable reuse'),p('有明的公開流程具有厭氧、無氧、好氧與生物膜過濾，部分出水另作回用。課程讓學徒區分水質處理鏈與再生水用途鏈。','Ariake documents anaerobic, anoxic, aerobic and biofilm-filter processes, with a portion further treated for reuse. The learner separates treatment and end-use chains.'),p('東京都下水道局介紹有明採A₂O和生物膜過濾，部分水另經臭氧或纖維過濾供沖廁與清洗等用途。','Tokyo Sewerage describes A₂O and biofilm filtration at Ariake, with part of the water further ozonated or fiber-filtered for toilet flushing and washing.'),'load hrt recycle nitrify denit phosphorus trickling ozone blend sensor',contexts(('分流污水入口','separate-sewer influent'),('反應槽停留','reactor retention'),('A₂O內回流','A₂O internal recycle'),('好氧區氨轉化','aerobic ammonia conversion'),('無氧區電子供體','anoxic electron donor'),('厭氧區磷循環','anaerobic phosphorus cycling'),('生物膜過濾床','biofilm filter bed'),('回用水臭氧子系統','reuse-water ozone subsystem'),('建築沖廁需求配對','building-flushing demand'),('處理與回用儀表','treatment/reuse instruments')),'ariake nutrient',('東京有明代表點','Tokyo Ariake reference point','日本','Japan',35.63,139.79),['分流污水~Separate sewage','A₂O~A₂O','沉澱~Settling','生物膜過濾~Biofilm filtration','回用深度處理~Reuse polishing','城市用途~Urban uses'])
course(409,p('化學強化初級處理與海域排放邊界','Chemically enhanced primary treatment and discharge boundary'),p('昂船洲課程以化學強化初級處理為主，不將其誤寫成活性污泥廠；學徒比較絮凝、沉澱、污泥及後端排放的質量去向。','This Stonecutters course focuses on chemically enhanced primary treatment rather than mislabeling it as activated sludge; the learner traces flocculation, settling, sludge and discharge.'),p('香港渠務署說明昂船洲以氯化鐵與聚合物促進懸浮物沉降，清液經消毒後排放。','Hong Kong DSD describes ferric chloride and polymer aiding suspended-solids settling, followed by disinfection of the clarified effluent before discharge.'),'peak velocity pump coag clarify removal sludge load sensor availability',contexts(('深層集水尖峰','deep-collection peaks'),('進水渠道','influent channel'),('提升泵組','lift pumps'),('瓶杯試驗加藥帳','jar-test chemical ledger'),('CEPT沉澱池','CEPT sedimentation basin'),('懸浮固體捕集','suspended-solids capture'),('化學污泥分流','chemical sludge stream'),('末端排放負荷','final discharge load'),('加藥流量水質連鎖','dose/flow/quality instrumentation'),('多列處理備援','multi-train treatment redundancy')),'stone cept',('香港代表點','Hong Kong reference point','香港','Hong Kong',22.32,114.15),['集水~Collection','提升~Lift','混凝膠凝~Coagulation/flocculation','初沉~Primary settling','消毒~Disinfection','污泥管理~Sludge management'])
course(410,p('都市半地下污水廠的水線與臭氣介面','Liquid treatment and odor interfaces in a semi-underground urban plant'),p('以迪化的都市整合廠為例，沿沉澱、深槽曝氣、污泥與回收水觀察。每個污染物流都需對應量測點，不能只看地上公園景觀。','Use Dihua as an urban integrated plant, following settling, deep-tank aeration, sludge and recycled water. Every pollutant stream needs a measurement point beyond the park landscape.'),p('臺北官方介紹迪化採雙層沉澱池、深槽階段曝氣二級生物處理與半地下配置，另設回收水處理。','Taipei documents double-deck settling, deep-tank staged aeration for secondary biological treatment and a semi-underground layout with recycled-water treatment.'),'load clarify hrt fm srt oxygen removal sludge blend sensor',contexts(('都市污水入口','urban wastewater entry'),('雙層沉澱面積辨識','double-deck settling area'),('深槽有效容積','deep-tank active volume'),('階段進水生物負荷','staged-feed biological load'),('回流排泥固體帳','return/waste sludge balance'),('深槽曝氣功率','deep-tank aeration power'),('出水質量驗證','effluent mass verification'),('污泥與臭氣介面','sludge/odor interface'),('回收水用途','recycled-water use'),('地下空間感測維護','underground-space instrumentation')),'dihua nutrient',TW,['進水~Influent','雙層沉澱~Double-deck settling','階段曝氣~Staged aeration','固液分離~Solids separation','回收水~Recycled water','污泥線~Sludge line'])
course(411,p('跨市初級處理與長期設備管理','Intermunicipal primary treatment and long-term asset management'),p('八里課程聚焦集水、初沉、污泥消化及放流介面，並把跨市流量與設備維護紀錄納入交接；不假設初沉已去除所有溶解污染。','Bali focuses on collection, primary settling, digestion and discharge, including intermunicipal flow and asset records; primary settling is not assumed to remove every dissolved pollutant.'),p('新北市官方資料記錄八里初沉與蛋型消化設施，並於2026年3月公布跨市管理移交；課程以此討論持續運轉的交接證據。','New Taipei records primary settling and egg-shaped digestion facilities and announced the intermunicipal management transfer in March2026; the course uses this to discuss continuity evidence.'),'load peak pump clarify removal sludge digestion methane sensor availability',contexts(('跨市集污邊界','intermunicipal collection boundary'),('尖峰流量配置','peak-flow allocation'),('進水提升設備','influent lift equipment'),('初級沉澱池','primary clarifier'),('溶解與顆粒污染區分','dissolved/particulate distinction'),('污泥濃縮輸送','sludge thickening/transfer'),('蛋型消化槽模型','egg-shaped digester model'),('消化氣計量','digester-gas metering'),('移交儀表校驗','handoff instrument checks'),('設備更新期間服務','service during equipment renewal')),'bali baliprocess nutrient',('新北八里代表點','Bali district reference point','臺灣','Taiwan',25.15,121.40),['跨市集水~Intermunicipal collection','提升~Lift','初級沉澱~Primary settling','放流~Discharge','污泥消化~Sludge digestion','維護交接~Asset handoff'])
course(412,p('初級污水處理的能力與限制','Capabilities and limits of primary wastewater treatment'),p('高雄中區官方定位為初級處理。本課讓學徒追蹤固體捕集與未去除的溶解負荷，評估提升、沉澱及放流監測，避免把處理程度混淆。','Kaohsiung Central is officially classified as primary treatment. Learners track captured solids and remaining dissolved loads while assessing pumping, settling and discharge monitoring.'),p('高雄市水利局公開資料將中區污水廠列為初級處理廠，並提供處理流程與營運資料供查核。','Kaohsiung Water Resources Bureau classifies the Central plant as primary treatment and provides process and operating information.'),'load peak velocity pump clarify removal sludge storage sensor availability',contexts(('市區收集負荷','urban collection load'),('雨天入滲尖峰','wet-weather inflow peak'),('攔污通水斷面','screen clear-flow section'),('進流泵能源','influent-pump energy'),('初沉池表面負荷','primary-settler surface loading'),('顆粒去除與溶解殘留','particle removal/dissolved residual'),('初沉污泥去向','primary-sludge destination'),('異常流量暫存','abnormal-flow buffering'),('放流量質同步','discharge flow/quality timing'),('數位監控及泵組備援','digital monitoring/pump redundancy')),'kaohsiung kcentral',('高雄代表點','Kaohsiung reference point','臺灣','Taiwan',22.62,120.30),['集污~Collection','攔污~Screening','抽送~Pumping','初沉~Primary settling','污泥~Sludge','放流監測~Discharge monitoring'])
course(413,p('垃圾焚化的物質、能源與排放帳','Material, energy and emission ledgers of incineration'),p('北投課程以進料秤重到灰渣出廠的整條物流為主線，加入中央控制室判讀與環境教育，要求學徒說清每一股副產物去向。','The Beitou course follows material from weighbridge to ash exit, adding control-room interpretation and environmental education; every residual stream must have a stated destination.'),p('北投焚化廠的官方環教介紹使用流程模型、語音與指示燈解說，並強調廢水、煙氣、底渣與飛灰的後續處理。','Beitou official education uses process models, narration and indicators and explains wastewater, flue gas, bottom ash and fly ash treatment.'),'load thermal steam efficiency bag stack ash heat sensor availability',contexts(('進出廠秤重','entry/exit weighing'),('垃圾混合熱值','mixed-waste heating value'),('鍋爐蒸汽生成','boiler steam generation'),('總發電與廠用電','gross power and auxiliaries'),('煙氣除塵模組','flue-gas dust module'),('控制室排放判讀','control-room emission reading'),('底渣飛灰分帳','separate ash ledgers'),('廠內熱回收','internal heat recovery'),('連續監測校正','continuous-monitor calibration'),('設備維護與暫存','maintenance and storage')),'beitou wte',TW,['過磅~Weighing','垃圾坑~Waste bunker','燃燒~Combustion','鍋爐~Boiler','煙氣處理~Gas treatment','灰渣~Ash streams'])
course(414,p('既有焚化廠延役與性能維持','Life extension and performance retention of an incinerator'),p('以大士南設備更新為案例，學習把鍋爐、吹灰、灰渣輸送、煙氣處理與起重設備視為相互依賴的系統；延役須有性能證據。','Using Tuas South refurbishment, treat boilers, soot blowing, ash transport, gas cleaning and cranes as interdependent systems; life extension requires performance evidence.'),p('NEA公布大士南焚化廠自2000年運作，延役計畫涉及鍋爐及相關設備更新；本課不把更新公告當作所有設備已完成驗收。','NEA reports operation since2000 and a life-extension program involving boilers and related equipment; an announcement is not treated as completed acceptance of every asset.'),'thermal steam efficiency bag stack ash netenergy sensor availability paired',contexts(('進料品質基線','feed-quality baseline'),('更新鍋爐熱量帳','refurbished boiler duty'),('延役前後淨效率','pre/post-refit net efficiency'),('煙氣除塵可用面積','available gas-cleaning area'),('排放質量與有效資料','emission mass and valid data'),('灰渣輸送介面','ash-conveyance interface'),('更新後廠用電','post-refit auxiliaries'),('新舊儀表一致性','old/new sensor consistency'),('分期停爐能力','phased shutdown capacity'),('氣候與垃圾組成對照','weather/composition controls')),'tuas wte',SG,['垃圾接收~Waste reception','爐排鍋爐~Grate/boiler','發電~Power','煙氣處理~Gas treatment','灰渣~Ash','延役驗證~Life-extension evidence'])

# Specialized modules prevent inappropriate reuse of water-line equations in waste/urban contexts.
method('weigh',p('地磅淨重與物流配對','Weighbridge net mass and matched consignments'),p('同一車次總重減空車重得到淨入料；班次總量需以唯一車次編號去重，才能與灰渣、儲坑庫存及能源帳相連。','Gross minus tare mass for one consignment gives net feed; deduplicated trip IDs connect shift totals to ash, bunker inventory and energy ledgers.'),p('同一車次總重18.6 t、空車重7.4 t','gross mass18.6 t and tare7.4 t for the same trip'),'mnet=mgross-mtare','18.6-7.4','t',p('僅適用同一車輛及相容含水狀態；燃料、乘員與附著水變化另計。','The same vehicle and compatible moisture basis are required; fuel, occupants and retained water changes are separate.'),p('核對車次編號、兩次秤重時間與零點檢查，再比對儲坑日末庫存。','Match trip ID, both weighing times and zero checks, then reconcile closing bunker stock.'),p('重複匯入車次或使用不同車輛空重會虛增進料；先封存原始票據再重算。','Duplicate trips or the wrong vehicle tare inflate feed; preserve raw tickets and recompute.'),p('所有垃圾車的空車重都可用一個常數。','One constant tare applies to every collection vehicle.'),p('只把總重改成20.1 t','change only gross mass to20.1 t'),'20.1-7.4')
method('districtheat',p('熱水迴路的有效供熱','Useful heat in a hot-water loop'),p('供回水溫差與水流量共同決定輸出熱功率；高供水溫度若沒有實際流量或可用負載，就不等於交付熱量。','Water flow and supply-return temperature difference determine delivered heat; a high supply temperature without flow or useful demand does not constitute heat delivery.'),p('水質量流率20 kg/s、比熱4.18 kJ/(kg·K)、供回水差20 K','water mass flow20 kg/s, heat capacity4.18 kJ/(kg·K) and supply-return difference20 K'),'Pheat=mdot cp ΔT','20*4.18*20','kW',p('單相水穩態近似；需在相同交付邊界量測，未扣管網散熱。','Steady single-phase water approximation with measurements at one delivery boundary; distribution losses are not deducted.'),p('用配對溫度探頭和流量表同步積分，與用戶熱量表比較。','Integrate synchronized matched temperature sensors and flow, then compare with the customer heat meter.'),p('回水短路會縮小有效溫差；檢查旁通與負載，而非只提高供水溫度。','A return-water shortcut reduces useful temperature difference; inspect bypasses and demand before changing supply temperature.'),p('發電量和供熱量可以直接相加成電效率。','Electricity and heat can be added directly as electrical efficiency.'),p('只把溫差改成15 K','change only temperature difference to15 K'),'20*4.18*15')
method('filterload',p('生物膜過濾的水力負荷','Hydraulic loading of a biofilm filter'),p('通過濾床的水量除以有效面積得到表觀濾速；同一流量遇到停用格或堵塞，剩餘濾格負擔會升高。','Flow through a bed divided by active area gives superficial filtration velocity; offline or blocked cells increase loading on the remaining cells.'),p('流量240 m³/h、可用濾床面積80 m²','flow240 m³/h and active filter area80 m²'),'vf=Q/A','240/80','m/h',p('僅為液體表觀濾速，不代替生物反應、氣水逆洗或實際孔隙速度。','Superficial liquid velocity only; biological kinetics, air-water backwash and pore velocity are separate.'),p('同時讀流量、濾前後水位及濁度，記錄停用濾格與反洗時段。','Read flow, upstream/downstream level and turbidity together; log offline cells and backwash periods.'),p('未扣反洗中的濾格會低估運轉負荷；先重算可用面積。','Counting a backwashing cell understates operating loading; recompute active area first.'),p('濾床越深，同一流量下表觀濾速必然越低。','A deeper bed necessarily lowers superficial velocity at equal flow.'),p('只把可用面積降到60 m²','reduce only active area to60 m²'),'240/60')
method('reusemass',p('整治材料回用與獨立驗收','Remediated-material reuse and independent acceptance'),p('回用比例只計入通過用途相符驗收的材料；處理過不代表所有粒級、所有污染物或所有用途均已合格。','Reuse fraction includes only material accepted for its intended use; treatment alone does not qualify every size fraction, contaminant or end use.'),p('處理乾土1000 t、符合指定回用條件760 t','treated dry soil1000 t and760 t meeting specified reuse acceptance'),'r=100 maccepted/minput','100*760/1000','%',p('教學驗收條件由題目假定，不代表任何司法管轄區標準；另查力學與浸出性質。','Acceptance is hypothetical, not a jurisdictional standard; geotechnical and leaching properties need separate checks.'),p('把每批採樣結果與回填位置綁定，保留不合格細料及出場聯單。','Link each batch sample to its placement and retain rejected-fines and off-site transfer records.'),p('把待驗材料算入回用會高估成果；先隔離待驗批次再更新帳。','Counting material awaiting testing inflates reuse; separate pending batches before updating the ledger.'),p('回用比例越高就能證明殘餘風險越低。','A higher reuse fraction proves lower residual risk.'),p('只把合格材料量改成680 t','change only accepted material to680 t'),'100*680/1000')
method('usable',p('總容積、保留量與可用調蓄','Gross, occupied and available storage'),p('可用調蓄是幾何容積扣除既存水量與不可用空間；模型必須把公共使用、沉積和事件前水位放進同一邊界。','Available storage is geometric volume less existing water and unusable space; public use, sediment and pre-event water level must share one accounting boundary.'),p('總容積500 m³、已有水120 m³、不可用容積30 m³','gross volume500 m³, existing water120 m³ and unusable volume30 m³'),'Vavailable=Vgross-Vexisting-Vunusable','500-120-30','m³',p('單一時間點幾何帳；不能取代事件水力或溢流路徑分析。','A geometric snapshot, not event routing or overflow-path analysis.'),p('用現況地形與水位重建水位—容積表，實測沉積厚度。','Rebuild the stage-storage table from surveyed geometry and level, measuring sediment thickness.'),p('把前場雨殘水當零會高估下一場能力；更新初始條件。','Assuming zero residual water overstates next-event capacity; update initial conditions.'),p('圖面總容積就是每次下雨時的可用容量。','Drawing capacity equals available capacity at every storm.'),p('只把已有水量升為200 m³','increase only existing water to200 m³'),'500-200-30')
method('orifice',p('出流孔口與水頭變化','Outlet orifice and changing head'),p('孔口流量近似與水頭平方根成正比，因此退水末期會變慢；固定流量估算只能是另有控制時的簡化。','Orifice flow is approximately proportional to the square root of head, so late drawdown slows; constant discharge is a simplification requiring separate control.'),p('流量係數Cd=0.62、孔口面積0.02 m²、孔心水頭h=0.5 m','Cd=0.62, outlet area0.02 m² and head above outlet center h=0.5 m'),'Q=Cd A sqrt(2gh)','0.62*0.02*(2*9.81*0.5)**0.5','m³/s',p('自由出流、穩態近似、無尾水淹沒或堵塞；係數為教學假定。','Quasi-steady free discharge without submergence or blockage; the coefficient is hypothetical.'),p('量測上游水位與下游尾水，再以容積變化核對流量。','Measure upstream level and tailwater, then verify discharge from volume change.'),p('下游管網頂托時自由出流式不再適用；切換淹沒邊界並保留溢流路徑。','Sewer backwater invalidates free discharge; use a submerged boundary and retain overflow routing.'),p('水頭降低一半時孔口流量也必然降低一半。','Halving head necessarily halves orifice discharge.'),p('只把水頭降為0.125 m','reduce only head to0.125 m'),'0.62*0.02*(2*9.81*0.125)**0.5')
method('capture',p('入口截留與旁通體積','Inlet capture and bypass volume'),p('地表逕流不一定全進入儲水空間；入口攔污、坡向與旁通共同決定實際捕獲量，缺少入口維護會使容積閒置仍淹水。','Surface runoff does not all enter storage; inlet debris, slope and bypass determine capture, so neglected inlets can cause flooding while storage remains empty.'),p('入流事件300 m³、假設捕獲比例0.85','event inflow300 m³ and assumed capture fraction0.85'),'Vbypass=Vin(1-fcapture)','300*(1-0.85)','m³',p('捕獲比例為事件平均假設；實際值需依水深、入口形狀和堵塞校準。','Event-average capture is assumed; actual values require depth-, geometry- and blockage-dependent calibration.'),p('比較上游逕流、入口與旁通流，雨後記錄攔污覆蓋率及清理前後差異。','Compare upstream runoff, inlet capture and bypass; document debris coverage and pre/post-cleaning differences.'),p('只擴大池體卻不處理入口阻塞無法提高捕獲；先查流路。','Enlarging storage without clearing a blocked inlet does not improve capture; inspect the route first.'),p('地圖上落在集水區內的雨水都必定進入水廣場。','All rainfall mapped in the catchment necessarily enters the watersquare.'),p('只把捕獲比例降成0.60','reduce only capture fraction to0.60'),'300*(1-0.60)')

# Replace methods whose assumptions belong to a different physical subsystem.
for code in ('b407','b413'):
    C[code]['keys']=['weigh' if k=='load' else 'districtheat' if k=='heat' else k for k in C[code]['keys']]
C['b408']['keys']=['filterload' if k=='trickling' else k for k in C['b408']['keys']]
