source('cheongoperation',p('清溪川概要與維持用水','Cheonggyecheon overview and maintenance water'),'https://www.sisul.or.kr/open_content/cheonggye/intro/summary.jsp','Seoul Facilities Corporation','turn34search4')

course(415,p('城市河川復育的水、能源與公共效益','Water, energy and public benefits of urban-stream restoration'),p('清溪川復育把水路帶回都市，也需要維持用水與公共管理。本課由集水與基流走到水力、能源、遮蔭和生態證據，分開評估景觀與河川功能。','Cheonggyecheon returned a water corridor to the city while requiring maintenance water and public management. Follow catchment and baseflow through hydraulics, energy, shade and ecological evidence, separating appearance from function.'),p('首爾官方記錄2003至2005年的復育工程；設施管理資料列出處理後漢江水及地下水等維持水源，顯示城市復育並非完全依賴自然基流。','Seoul records restoration during2003–2005; its facilities operator lists treated Han River water and groundwater among maintenance sources, demonstrating that restoration does not rely solely on natural baseflow.'),'runoff blend velocity manning pump heatshade habitat ecology sensor paired',contexts(('城市集水區與暴雨邊界','urban catchment and storm boundary'),('維持用水來源配對','maintenance-water source matching'),('溪床斷面與人行空間','channel section and pedestrian space'),('橋梁間水路粗糙度','between-bridge channel roughness'),('補注供水能源帳','maintenance-supply energy ledger'),('沿岸遮蔭樣區','riverside shade plots'),('狹長河岸棲地','linear riparian habitat'),('物種與季節調查','species and seasonal surveys'),('水位水質監測對照','level/quality sensor comparison'),('復育前後與對照街區','before-after and control streets')),'cheongcity cheongoperation cheongstudy',('首爾代表點','Seoul reference point','南韓','South Korea',37.57,126.98),['集水與供水~Catchment and supply','溪流~Stream','水岸~Waterfront','遮蔭~Shade','棲地~Habitat','長期評估~Long-term assessment'])
course(416,p('自然化河川與可淹水公園的共同設計','Co-design of a naturalized river and floodable park'),p('碧山—宏茂橋公園讓河川與公園共享空間；學徒需同時追蹤洪水佔用、河岸侵蝕、生態棲地與晴天活動，不把草地一律視為永久乾燥。','Bishan–Ang Mo Kio Park shares space between river and park; learners track flood occupation, erosion, habitat and dry-weather use without assuming lawns stay permanently dry.'),p('NParks與設計團隊介紹將混凝土渠道轉為自然化河川，河岸公園可在暴雨時承接較多水量。','NParks and the design team describe converting a concrete channel to a naturalized river, with adjacent parkland accommodating more water during storms.'),'runoff storage infiltration manning shear habitat ecology heatshade sensor paired',contexts(('上游集水與公園入口','upstream catchment and park entry'),('公園可淹水區','floodable park zones'),('土壤入滲試驗區','soil-infiltration trial plots'),('彎曲河道通洪','meandering-channel conveyance'),('河岸生物工程抗蝕','bioengineered-bank erosion resistance'),('河岸廊道連續性','riparian-corridor continuity'),('棲地監測樣帶','habitat monitoring transects'),('樹冠與活動區熱暴露','canopy and recreation heat exposure'),('水位警示資料品質','level-warning data quality'),('修復成效與對照河段','restoration outcomes and control reach')),'bishan bishandesign',SG,['上游逕流~Upstream runoff','自然河道~Naturalized channel','可淹公園~Floodable park','植生河岸~Vegetated bank','棲地~Habitat','監測~Monitoring'])
course(417,p('棕地污染分流、土壤清洗與回用證據','Brownfield segregation, soil washing and reuse evidence'),p('以倫敦奧運場址整治為參考，先建立土壤—地下水概念模型，再追蹤粒級、洗水、殘渣與合格回填批次。土地變綠不能代替污染物驗收。','Using the London Olympic site as a reference, build a soil-groundwater conceptual model and trace size fractions, washwater, residuals and accepted backfill. Green appearance does not replace contaminant acceptance.'),p('工程承包商DEME記錄倫敦奧運場址的土壤整治與材料回用；本課以EPA土壤清洗機理分析污染在細料及洗水間的轉移。','Contractor DEME documents soil remediation and material reuse at the London Olympic site; the lesson uses EPA soil-washing principles to analyze transfer into fines and washwater.'),'soil soilwash load clarify reusemass darcy travel sensor habitat paired',contexts(('污染分區與乾土盤點','contamination zoning and dry-soil inventory'),('洗土粒級分離','wash-plant fractionation'),('洗水循環污染帳','recirculated-washwater pollutant ledger'),('細料與洗水固液分離','fines/washwater separation'),('回填批次追溯','accepted-backfill batch traceability'),('地下水源—途徑—受體','groundwater source-pathway-receptor'),('觀測井傳輸時間','monitoring-well transport time'),('現地量測與實驗室校驗','field/laboratory cross-check'),('修復後植栽土層','post-remediation planting soil'),('施工前後風險證據','pre/post-construction risk evidence')),'olympic soilwash',('倫敦奧林匹克公園代表點','London Olympic Park reference point','英國','United Kingdom',51.54,-0.01),['調查分區~Site zoning','分選~Sorting','土壤清洗~Soil washing','洗水處理~Washwater treatment','驗收回用~Acceptance/reuse','長期監測~Long-term monitoring'])
course(418,p('掩埋場覆蓋、氣水控制與長期公園管理','Landfill cover, gas/water controls and long-term park stewardship'),p('Freshkills的公園功能建立在掩埋場工程覆蓋與持續監測之上。學徒要把雨水、滲出水、氣體、沉陷和植被畫成分開但互相影響的路徑。','Freshkills park functions above engineered landfill containment and monitoring. Learners separate, then reconnect, stormwater, leachate, gas, settlement and vegetation pathways.'),p('NYC Parks介紹Freshkills由掩埋場轉型公園，場址仍包含封蓋及環境控制；開放空間不表示廢棄物已移除或後續管理已結束。','NYC Parks describes the landfill-to-park transformation with continuing cap and environmental controls; public open space does not mean the waste was removed or stewardship ended.'),'landfillwater runoff drawdown gas settlement pump habitat ecology sensor availability',contexts(('覆蓋層水量邊界','cover-system water balance'),('坡面雨水逕流','slope stormwater runoff'),('排水溝與滯洪退水','ditch and detention drawdown'),('掩埋氣收集支線','landfill-gas collection laterals'),('不均勻沉陷巡測','differential-settlement survey'),('滲出水輸送能源','leachate-conveyance energy'),('植根與覆蓋層相容','root/cover compatibility'),('草地棲地追蹤','grassland-habitat tracking'),('氣水儀表漂移','gas/water instrument drift'),('長期控制設備備援','long-term control redundancy')),'freshkills freshkillsengineering',('紐約史泰登島代表點','Staten Island reference point','美國','United States',40.58,-74.19),['工程覆蓋~Engineered cover','雨水排除~Stormwater drainage','滲出水~Leachate','掩埋氣~Landfill gas','沉陷監測~Settlement survey','公園維護~Park stewardship'])
course(419,p('污水地下化與河川生態復育的先後依賴','Dependence of river restoration on separated sewer infrastructure'),p('埃姆舍轉型先把污水從河道移入管網與處理系統，再改善河岸與棲地。學徒需檢查污水未分離時，單做景觀能否持續維持水質。','The Emscher transformation moves sewage from the river into sewers and treatment before restoring banks and habitat. Learners assess whether landscaping alone can sustain water quality without sewage separation.'),p('Emschergenossenschaft介紹埃姆舍流域以污水幹管、處理廠及河川重整共同完成轉型，強調流域尺度工程的相互依賴。','Emschergenossenschaft describes basin transformation through sewers, treatment plants and river restructuring, emphasizing interdependent infrastructure.'),'load velocity manning pump removal runoff shear habitat ecology paired',contexts(('污水與雨水來源分類','sewage/stormwater source separation'),('新污水幹管斷面','new sewer-trunk section'),('河道與幹管不同邊界','river/sewer hydraulic boundaries'),('低地提升系統','lowland lift system'),('處理廠與河道質量帳','treatment/river mass ledger'),('雨天面源逕流','wet-weather diffuse runoff'),('恢復河岸沖蝕','restored-bank shear'),('河川廊道連接','river-corridor linkage'),('底棲與岸帶調查','benthic/riparian surveys'),('流域修復成效歸因','basin-restoration attribution')),'emscher emscherinfra nutrient',('埃森代表點','Essen reference point','德國','Germany',51.46,7.01),['污染源~Pollution sources','污水幹管~Sewer trunk','處理廠~Treatment','河道整治~River restructuring','棲地連結~Habitat linkage','流域監測~Basin monitoring'])
course(420,p('乾天公共空間與雨天調蓄的切換','Switching between dry-weather public use and storm storage'),p('Benthemplein把城市活動空間兼作暴雨調蓄。學徒由屋頂集水走到入口、分池、出流與乾天恢復，辨認容量足夠但入口堵塞或下游頂托的失敗情境。','Benthemplein combines civic activity with storm storage. Follow roof catchments, inlets, basins, outlets and recovery, identifying failure despite sufficient volume when inlets block or downstream backwater occurs.'),p('De Urbanisten的專案記錄把水廣場定位為公共空間與雨水調蓄的結合，並以不同池體與表面水路讓水循環可見。','De Urbanisten describes the watersquare as combined public space and stormwater storage, with basins and surface routes making the water cycle visible.'),'runoff capture velocity usable storage orifice drawdown manning sensor paired',contexts(('屋頂與鋪面集水','roof/pavement catchment'),('入口攔污與旁通','inlet debris and bypass'),('地表導水溝','surface conveyance gutter'),('各池事件前可用容積','pre-event available basin volumes'),('暴雨分池水量帳','storm basin-routing ledger'),('孔口與尾水條件','outlet and tailwater conditions'),('雨後公共使用恢復','post-storm public-use recovery'),('導水溝沉積粗糙度','gutter sediment roughness'),('池水位與降雨紀錄','basin level/rainfall records'),('淹水改善與鄰近對照','flood improvement and nearby control')),'benthem watersquares',('鹿特丹代表點','Rotterdam reference point','荷蘭','Netherlands',51.92,4.48),['屋頂鋪面~Roofs/pavement','導水入口~Inlets','淺池~Shallow basins','深池~Deep basin','控制出流~Controlled outlet','公共空間恢復~Public-use recovery'])

LAB=('虛擬水處理實驗室','Virtual water-treatment laboratory','教學情境','Educational setting',0,0)
course(421,p('以質量、氧量及固體年齡建立曝氣槽','Aeration-basin reasoning from mass, oxygen and solids age'),p('在虛擬實驗室設計活性污泥水線，依序確定進料、容積、生物量、排泥、需氧與沉澱介面。使用簡化模型比較方案，所有數字均非任何實廠設定。','Design an activated-sludge liquid line in a virtual laboratory: establish feed, volume, biomass, wasting, oxygen and clarification interfaces. Compare options with simplified models; no number is an actual plant setting.'),p('活性污泥把懸浮微生物反應與後續固液分離結合；EPA營養鹽設計手冊提供反應槽、固體年齡與脫氮除磷的整合背景。','Activated sludge combines suspended microbial reaction and solids separation; EPA nutrient guidance provides integrated background for reactors, solids age and nutrient removal.'),'load hrt fm srt oxygen nitrify denit recycle clarify sensor',contexts(('設計日進料邊界','design-day influent boundary'),('曝氣槽有效容積','aeration-basin active volume'),('有機負荷與微生物庫存','organic food/biomass inventory'),('排泥與固體年齡','wasting and solids age'),('鼓風需氧與現場效率','oxygen and field-transfer efficiency'),('硝化額外需氧','additional nitrification oxygen'),('前置無氧區碳源','pre-anoxic carbon source'),('內回流與水力負荷','internal recycle and hydraulics'),('二沉池固液分離','secondary clarification'),('DO、流量與實驗室交叉核對','DO/flow/laboratory cross-check')),'nutrient iwtt',LAB,['進料~Feed','反應槽~Reactor','曝氣~Aeration','內回流~Internal recycle','二沉~Clarifier','排泥控制~Wasting control'])
course(422,p('將時間分區轉成可驗證的批次狀態機','Verifiable batch states from time-separated treatment'),p('SBR在同一槽以時間切換進水、反應、沉澱與排水。學徒建立兩槽排程及事件紀錄，檢查每次切換前條件，而非只按固定計時器。','An SBR sequences filling, reaction, settling and decant in one basin. Build a two-basin schedule and event log, checking transition conditions rather than relying only on a timer.'),p('EPA序批式反應槽資料說明以批次週期整合反應與沉澱；本課將其轉為可追蹤的教學狀態，不提供實廠自動控制程式。','EPA describes batch-cycle integration of reaction and settling; this lesson turns it into traceable educational states rather than live plant-control code.'),'load storage cycle hrt oxygen nitrify denit decant duty srt',contexts(('每批污染質量輸入','per-batch pollutant input'),('兩批之間進水緩衝','interbatch influent buffer'),('雙槽週期與日能力','two-basin cycles/daily capacity'),('反應期有效水量','reaction-period effective volume'),('曝氣階段供氧','aerated-phase oxygen'),('氨轉化與週期終點','ammonia conversion/cycle endpoint'),('缺氧階段電子供體','anoxic-phase donor'),('沉澱後排水介面','post-settling decant interface'),('曝氣時間與日耗電','aeration time/daily energy'),('跨批次排泥與菌齡','cross-cycle wasting/solids age')),'sbr nutrient',LAB,['進水~Fill','反應~React','沉澱~Settle','排水~Decant','閒置排泥~Idle/waste','下一批~Next batch'])
course(423,p('生物反應與膜分離的相互限制','Coupled limits of biological reaction and membrane separation'),p('MBR把生物處理與膜固液分離結合。學徒同時追蹤污泥、需氧、淨產水與膜壓差；膜能截留固體不代表所有溶解物已被破壞。','MBR couples biology with membrane solids separation. Track sludge, oxygen, net production and membrane pressure together; solids retention does not imply destruction of every dissolved substance.'),p('EPA膜生物反應器資料介紹以膜取代傳統固液分離的配置與維護需求；課程採開放機理，不指定膜產品運轉條件。','EPA describes membrane-based solids separation and maintenance requirements; this course uses general mechanisms without prescribing product operating conditions.'),'load fm srt oxygen mf tmp filterload sludge sensor availability',contexts(('預處理後進料品質','post-pretreatment feed quality'),('高生物量負荷判讀','high-biomass loading interpretation'),('污泥齡及排泥','solids age and wasting'),('生物需氧與膜擦洗分帳','biological oxygen/membrane scour ledgers'),('產水膜列淨通量','membrane-train net flux'),('跨膜壓差趨勢','transmembrane-pressure trend'),('膜前顆粒濾床選項','optional pre-membrane granular filter'),('剩餘污泥處置','waste-sludge handling'),('水質與壓差感測校驗','quality/pressure instrument checks'),('離線清洗期間可用能力','capacity during offline cleaning')),'mbr nutrient',LAB,['進料前處理~Feed pretreatment','生物反應~Bioreaction','供氧~Oxygen supply','膜分離~Membrane separation','產水~Permeate','污泥與維護~Sludge/maintenance'])
course(424,p('載體有效面積、生物膜傳質與攔網','Carrier area, biofilm transport and retaining screens'),p('MBBR以移動載體提供附著生物膜表面，水流、載體混合與供氧共同影響反應。學徒區分名目填充比例、受保護面積、實際活性與攔網通水。','MBBR uses moving carriers for attached biofilm; flow, carrier mixing and oxygen jointly affect reaction. Distinguish fill fraction, protected area, actual activity and retaining-screen hydraulics.'),p('AnoxKaldnes技術資料介紹移動載體生物膜反應器，EPA技術資料提供污水處理比較背景；本課不把廠商面積值視為保證去除率。','AnoxKaldnes documents moving-carrier biofilm reactors, with EPA information providing treatment context; manufacturer surface area is not treated as guaranteed removal.'),'load hrt carrier surface diffusion oxygen screen nitrify removal clarify',contexts(('可生物降解進料','biodegradable feed'),('移動床有效反應容積','moving-bed effective volume'),('載體受保護面積','protected carrier area'),('單位附著面積負荷','attached-area loading'),('膜厚與傳質路徑','film thickness/transport path'),('混合與需氧分辨','mixing/oxygen distinction'),('載體出口攔網','carrier-retaining outlet screen'),('硝化生物膜需氧','nitrifying-film oxygen'),('水相轉化與脫落固體','conversion/detached solids'),('後段固液分離','downstream solids separation')),'mbbr iwtt nutrient',LAB,['進料~Feed','移動載體~Moving carriers','附著生物膜~Biofilm','供氧混合~Oxygen/mixing','攔網~Retaining screen','固液分離~Solids separation'])
course(425,p('布水、生物膜與後段沉澱的串連','Connecting distribution, biofilm and downstream settling'),p('生物濾池讓水流經附著生物膜的介質；布水與通風維持反應，脫落生物膜仍需處理。學徒從預沉走到回流、傳質和終沉，區分過濾與生物轉化。','Trickling filters pass water over attached-film media; distribution and ventilation support reaction while sloughed biomass still needs treatment. Follow primary settling, recycle, transport and final settling, distinguishing filtration from conversion.'),p('EPA生物濾池資料描述介質、布水、通風與固體分離；名稱中的濾池不代表僅靠篩孔截留污染。','EPA describes media, distribution, ventilation and solids separation; the word filter does not mean pollutants are removed only by sieving.'),'load clarify trickling surface diffusion recycle oxygen removal sludge sensor',contexts(('初沉前有機負荷','organic load before primary settling'),('介質前顆粒保護','particle protection before media'),('旋轉布水與回流水量','rotating distribution/recycle flow'),('生物膜有效表面負荷','effective film surface loading'),('液膜與生物膜傳質','liquid/biological-film transport'),('回流改善濕潤與水力代價','recycle wetting/hydraulic tradeoff'),('通風供氧需求','ventilation oxygen demand'),('溶解有機物去除驗證','dissolved-organic removal evidence'),('脫膜污泥與終沉','sloughed sludge/final settling'),('布水不均與儀表檢查','uneven distribution/instrument checks')),'trickling nutrient',LAB,['初級處理~Primary treatment','布水~Distribution','生物膜介質~Biofilm media','通風~Ventilation','終沉~Final settling','回流與污泥~Recycle/sludge'])

method('netflux',p('膜抽吸週期與淨產水','Membrane suction cycles and net production'),p('膜列反洗或鬆弛時不產水，日平均通量低於抽吸期間通量；若還耗用產水反洗，需另扣反洗體積。','Backwash or relaxation interrupts production, so time-averaged flux is lower than suction-period flux; permeate used for backwash must also be deducted.'),p('抽吸通量30 L/(m²·h)、每10分鐘抽吸8分鐘，先忽略反洗耗水','suction flux30 L/(m²·h),8 minutes suction per10-minute cycle, initially ignoring backwash water'),'Jnet=Jsuction tsuction/tcycle','30*8/10','L/(m²·h)',p('重複穩態週期且抽吸通量固定；不是膜產品的允許週期。','Repeated steady cycles and constant suction flux; this is not a permissible product operating cycle.'),p('用產水總表核對整日淨產水，並區分反洗回流、排放及停機。','Reconcile daily net permeate with a totalizer and distinguish backwash return, disposal and downtime.'),p('用抽吸瞬間通量推算全天產水會高估能力；先重建時間帳。','Extrapolating instantaneous suction flux over the full day overstates capacity; reconstruct the time ledger.'),p('膜停止抽吸時仍可用相同通量計入產水。','An offline suction period can be credited with the same permeate flux.'),p('只把每10分鐘抽吸時間降為7分鐘','reduce only suction time to7 of every10 minutes'),'30*7/10')
method('air',p('通風氣量與可轉移氧量','Ventilation flow and transferable oxygen'),p('進入濾床的氧氣只有一部分轉移到濕潤生物膜；空氣量足夠不代表分配均勻或氧已到達生物膜深處。','Only part of the oxygen entering a filter transfers to the wet biofilm; enough air volume does not prove uniform distribution or oxygen penetration.'),p('同一參考溫壓下空氣500 m³/h、含氧質量0.28 kg/m³、假設轉移比例0.10','air500 m³/h at one reference state, oxygen content0.28 kg/m³ and assumed transfer fraction0.10'),'Otransfer=Qair cO2 ftransfer','500*0.28*0.10','kg O₂/h',p('教學轉移比例須以實測校正；自然通風隨氣溫與濾床阻力變化，不能保證固定風量。','The hypothetical transfer fraction requires measurement; natural ventilation varies with temperature and bed resistance, so airflow is not guaranteed constant.'),p('比較進出氣氧量與溫壓，觀察排水層、通氣口及濾床含水分布。','Compare inlet/outlet oxygen on matched pressure/temperature bases and inspect underdrains, vents and bed wetting.'),p('積水堵住通氣路徑會限制供氧；先診斷排水與通風阻力。','Ponding can obstruct ventilation and limit oxygen; diagnose drainage and airflow resistance first.'),p('空氣中含氧就表示生物膜每一層都不缺氧。','Oxygen in air means every biofilm layer is adequately oxygenated.'),p('只把轉移比例改成0.06','change only transfer fraction to0.06'),'500*0.28*0.06')
C['b423']['keys']=['netflux' if k=='filterload' else k for k in C['b423']['keys']]
