# English prose spacing is deliberately normalized only for number-adjacent words.
def split(v):
    z,e=v.split('~',1)
    assert z.strip() and e.strip()
    return z,e

def result(expr):
    clean=expr.replace('math.','')
    env={n:getattr(math,n) for n in ('sqrt','log','log10','exp','pi','e')}
    env.update(abs=abs,min=min,max=max,round=round)
    value=eval(clean,{'__builtins__':{}},env)
    assert isinstance(value,(int,float)) and math.isfinite(value),expr
    return clean,value

def display(value): return f'{value:.7g}'

def generate(code,c):
    target=TARGETS[code]
    n=int(code[1:])
    discipline='environment-urban' if n in (415,416,419,420) else 'environment-waste' if n in (407,413,414,417,418) else 'environment-water'
    place=c['place']
    title=p(target['title'],target['titleEn'])
    summary=c['context']
    output=dict(id=code,title=title,focus=c['focus'],summary=summary,discipline=discipline,units=[],sources=[{k:v for k,v in S[key].items() if k!='evidenceRef'} for key in c['sources']],place=dict(name=place[0],nameEn=place[1],country=place[2],countryEn=place[3],lat=place[4],lon=place[5],coordinateScope='Method-source institution area only; not a treatment plant or entrance. Rounded from the area map linked by official EPA headquarters page.' if n>=421 else 'approximate-city-reference; not a facility entrance'),history=c['history'],architectureNodes=c['nodes'],modelChecks=[])
    for i,(key,context) in enumerate(zip(c['keys'],c['contexts'])):
        m=M[key]
        tz,te=split(m['title']);cz,ce=split(context)
        mz,me=split(m['mechanism']);gz,ge=split(m['givens']);bz,be=split(m['boundary']);vz,ve=split(m['verify']);fz,fe=split(m['failure']);wz,we=split(m['wrong']);xz,xe=split(m['change'])
        expr,value=result(m['expr']);expr2,value2=result(m['expr2'])
        unit=dict(
            title=p(cz+'：'+tz,ce[0].upper()+ce[1:]+': '+te),
            mechanism=p(mz+'本單元在「'+cz+'」觀察此因果關係。',me+' Examine this relationship at '+ce+'.'),
            model=p('明示假設的教學子模型，非場址量測：'+gz+'。公式 '+m['formula']+'；代入 '+expr+' = '+display(value)+' '+m['unit']+'。適用邊界：'+bz,'Explicitly hypothetical teaching submodel, not site measurements: '+ge+'. Formula '+m['formula']+'; substitution '+expr+' = '+display(value)+' '+m['unit']+'. Boundary: '+be),
            verify=p(vz+'在離線場景為「'+cz+'」建立證據表，把原始值、單位、時戳及修正值分開保留。',ve+' Build an offline evidence table for '+ce+'; retain raw values, units, timestamps and corrected values separately.'),
            failure=p(fz+'在場景中標出故障點及其影響的上下游證據。',fe+' Mark the fault and the upstream/downstream evidence it affects in the scene.'),
            misconception=p(wz,we),
            practice=p('先點選「'+cz+'」量測點並重現基準算例；接著'+xz+'，其他條件不變，預測後重算得到 '+display(value2)+' '+m['unit']+'。與基準 '+display(value)+' '+m['unit']+'比較，說明改變的機制；若現場資料不符，依驗證項檢查假設，不能直接套用成設備設定。','Select the '+ce+' measurement point and reproduce the baseline; then '+xe+' with other inputs fixed. Predict and recompute '+display(value2)+' '+m['unit']+'. Compare with baseline '+display(value)+' '+m['unit']+' and explain the mechanism; if observations disagree, check the stated assumptions rather than converting the example directly into equipment settings.')
        )
        output['units'].append(unit)
        output['modelChecks'].extend([
            dict(expression=expr,expected=value,unit=m['unit'],description=p(f'單元{i+1}基準：{cz}',f'Unit{i+1} baseline: {ce}')),
            dict(expression=expr2,expected=value2,unit=m['unit'],description=p(f'單元{i+1}變量實驗：{xz}',f'Unit{i+1} changed-input experiment: {xe}'))])
    assert len(output['units'])==10 and len(output['modelChecks'])==20 and len(output['sources'])>=2
    for u in output['units']:
        assert set(u)=={'title','mechanism','model','verify','failure','misconception','practice'}
        for v in u.values():
            assert v.count('~')==1,v
            split(v)
    return output

if __name__=='__main__':
    outdir=ROOT/'inputs';outdir.mkdir(exist_ok=True)
    generated=[]
    for code,c in sorted(C.items()):
        data=generate(code,c)
        (outdir/(code+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
        generated.append(dict(id=code,units=len(data['units']),modelChecks=len(data['modelChecks']),sources=len(data['sources']),bytes=(outdir/(code+'.json')).stat().st_size))
    assert len(generated)==25
    (Path(__file__).parent/'source_records.json').write_text(json.dumps(S,ensure_ascii=False,indent=2)+'\n')
    (Path(__file__).parent/'author_validation.json').write_text(json.dumps(dict(courses=25,units=250,modelChecks=500,methods=len(M),results=generated),ensure_ascii=False,indent=2)+'\n')
    print(json.dumps(dict(courses=len(generated),units=250,checks=500,methods=len(M),bytes=sum(x['bytes'] for x in generated))))
